      "image": "https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEgB7bCjg0mXHv-k6qhUIYxC3k8pfyDz6KIq1rmbwi1lqCjWCRdCeTIAP0MCrF0HGxsmc9HGc71zKERsKg8jmYfCCMTTcZRMTkfItJB_lhz2eeiWC7YJgr3ETCCNAlMiCfUuhGewBS9fY-11IBmzF8BabuVxVhyphenhyphenNsCZV8OcVbW_xZnBSUAOGm9QwVwUhNTA/s1200/Gemini_Generated_Image_e55f4ze55f4ze55f%20%281%29.jpg",
