head.script:
//
window.PXL_WORKER_BASE_URL = 'https://px-league-proxy.pxleague.workers.dev';   // e.g. 'https://px-api.your-name.workers.dev'
// The Worker answers only the origins in its ALLOWED_ORIGINS list (blogger/worker/src/index.js):
// https://www.px-league.site and https://px-league.site. A new domain must be added there too.
window.PXL_SITE_URL = 'https://www.px-league.site';
(function () {
  var theme = 'light';
  try { theme = localStorage.getItem('pxl-theme') === 'dark' ? 'dark' : 'light'; } catch (e) {}
  document.documentElement.setAttribute('data-theme', theme);
})();
// Client-side routing for the standings / match pages. Blogger's URL
// comparisons in <b:if> evaluate to false on this blog, so the route is
// picked here from location.pathname. The CSS hides #main for these
// routes before the first paint, so the empty page article never flashes.
window.PXL_ROUTE = ({ '/p/standings.html': 'standings', '/p/match.html': 'match', '/p/predictions.html': 'predictions',
   '/p/matches.html': 'matches', '/p/app.html': 'app', '/p/news.html': 'news' })[location.pathname] || '';
if (window.PXL_ROUTE) document.documentElement.setAttribute('data-pxl-route', window.PXL_ROUTE);

// ---------------------------------------------------------------------------
// Dynamic SEO for the client-side routes. Blogger renders these as one static
// page each, so their title / description / canonical are set here (Google
// indexes the rendered DOM). pxlSeo.set() is also called by the match script
// once the match data has loaded.
window.pxlSeo = (function () {
  var SITE = 'PX League';
  function meta(attr, key, value) {
    if (!value) return;
    var el = document.head.querySelector('meta[' + attr + '="' + key + '"]');
    if (!el) { el = document.createElement('meta'); el.setAttribute(attr, key); document.head.appendChild(el); }
    if (el.getAttribute('content') !== value) el.setAttribute('content', value);
  }
  function set(o) {
    if (o.title) {
      if (document.title !== o.title) document.title = o.title;
      meta('property', 'og:title', o.title);
      meta('name', 'twitter:title', o.title);
    }
    if (o.description) {
      meta('name', 'description', o.description);
      meta('property', 'og:description', o.description);
      meta('name', 'twitter:description', o.description);
    }
    if (o.image) {
      meta('property', 'og:image', o.image);
      meta('name', 'twitter:image', o.image);
    }
    if (o.robots) meta('name', 'robots', o.robots);
    if (o.url) {
      var link = document.getElementById('pxl-canonical') || document.querySelector('link[rel="canonical"]');
      if (!link) { link = document.createElement('link'); link.rel = 'canonical'; document.head.appendChild(link); }
      if (link.href !== o.url) link.href = o.url;
      meta('property', 'og:url', o.url);
    }
  }
  // One JSON-LD block per id; rewritten only when its content changed.
  function jsonLd(id, data) {
    var el = document.getElementById(id);
    if (!data) { if (el) el.remove(); return; }
    var text = JSON.stringify(data);
    if (!el) { el = document.createElement('script'); el.type = 'application/ld+json'; el.id = id; document.head.appendChild(el); }
    if (el.textContent !== text) el.textContent = text;
  }
  return { set: set, jsonLd: jsonLd, site: SITE };
})();

(function () {
  var base = (window.PXL_SITE_URL || location.origin).replace(/\/+$/, '');
  var ROUTES = {
    standings: { title: 'ترتيب الدوريات | PX League',
      description: 'جداول ترتيب الدوري الإنجليزي والإسباني والإيطالي والألماني والفرنسي ودوري روشن السعودي والدوري المصري وأبطال أوروبا، محدّثة بعد كل جولة.' },
    matches: { title: 'مركز المباريات: نتائج ومواعيد اليوم والأمس والغد | PX League',
      description: 'جدول مباريات كرة القدم لأي يوم مع النتائج المباشرة وحالة كل مباراة وتصفية حسب الدوري، بتوقيت القاهرة.' },
    predictions: { title: 'توقعات المباريات | PX League',
      description: 'توقّع نتائج مباريات اليوم واجمع النقاط ونافس في ترتيب المتوقعين على PX League.' },
    app: { title: 'تطبيق PX League لأندرويد وآيفون',
      description: 'حمّل تطبيق PX League: نتائج المباريات لحظة بلحظة، الأخبار، التوقعات والدوريات الخاصة مع أصدقائك.' },
    news: { title: 'الأخبار: آخر أخبار كرة القدم وتحليلات المباريات | PX League',
      description: 'أرشيف أخبار PX League: تقارير المباريات، تحليلات القمم، أخبار الأندية والمنتخبات العربية والعالمية، ومتابعة الدوريات الكبرى يومًا بيوم.' },
    match: { title: 'تفاصيل المباراة | PX League',
      description: 'تفاصيل المباراة: النتيجة المباشرة، أحداث اللقاء، التشكيلات، الملعب والحكم والقناة الناقلة على PX League.' }
  };
  var r = ROUTES[window.PXL_ROUTE];
  if (!r) return;
  var url = base + location.pathname;
  var robots = null;
  if (window.PXL_ROUTE === 'match') {
    // /p/match.html?id=123 is one page per match: the id stays in the canonical URL.
    // Without a valid id the page has no content of its own and is kept out of the index.
    var id = new URLSearchParams(location.search).get('id') || '';
    if (/^\d{1,12}$/.test(id)) url += '?id=' + id; else robots = 'noindex, follow';
  }
  if (window.PXL_ROUTE === 'news') {
    // /p/news.html?page=N: every archive page is its own canonical URL (page 1 has no parameter).
    var pg = parseInt(new URLSearchParams(location.search).get('page'), 10);
    if (pg > 1 && pg < 10000) { url += '?page=' + pg; r = { title: r.title.replace(' | ', ' - صفحة ' + pg + ' | '), description: r.description }; }
  }
  window.pxlSeo.set({ title: r.title, description: r.description, url: url, robots: robots });
})();
//

head.b:skin:
/* ==========================================================================
   1. Design tokens (light = default, dark = [data-theme="dark"])
   ========================================================================== */
:root {
  --brand: #32cd32;
  --brand-strong: #22a822;
  --brand-ink: #04120a;
  --brand-soft: rgba(50, 205, 50, 0.12);
  --brand-glow: 0 0 0 rgba(50, 205, 50, 0);

  --bg: #f8f9fa;
  --surface: #ffffff;
  --surface-2: #f0f2f5;
  --surface-glass: rgba(255, 255, 255, 0.85);
  --border: #e3e6eb;
  --text: #15181d;
  --text-muted: #5f6772;
  --shadow: 0 1px 2px rgba(16, 24, 40, 0.06), 0 6px 18px rgba(16, 24, 40, 0.06);
  --shadow-hover: 0 4px 10px rgba(16, 24, 40, 0.08), 0 16px 32px rgba(16, 24, 40, 0.10);
  --live: #e11d48;
  --live-soft: rgba(225, 29, 72, 0.10);
  --card-shadow: 0 4px 12px rgba(0, 0, 0, 0.05);
  --card-head: #f4f5f7;

  --radius: 14px;
  --radius-sm: 9px;
  --container: 1240px;
  --header-h: 64px;
  --font: 'Cairo', Tahoma, 'Segoe UI', Arial, sans-serif;
}

[data-theme="dark"] {
  --brand: #3ee63e;
  --brand-strong: #32cd32;
  --brand-soft: rgba(62, 230, 62, 0.14);
  --brand-glow: 0 0 22px rgba(62, 230, 62, 0.35);

  --bg: #07090c;
  --surface: #10141a;
  --surface-2: #161b23;
  --surface-glass: rgba(14, 18, 24, 0.72);
  --border: rgba(255, 255, 255, 0.08);
  --text: #f2f5f8;
  --text-muted: #9aa4b1;
  --shadow: 0 1px 2px rgba(0, 0, 0, 0.5), 0 10px 26px rgba(0, 0, 0, 0.35);
  --shadow-hover: 0 0 0 1px rgba(62, 230, 62, 0.35), 0 18px 40px rgba(0, 0, 0, 0.55);
  --live: #ff3b5c;
  --live-soft: rgba(255, 59, 92, 0.14);
  --card-shadow: 0 1px 2px rgba(0, 0, 0, 0.5), 0 8px 22px rgba(0, 0, 0, 0.35);
  --card-head: rgba(255, 255, 255, 0.03);
  color-scheme: dark;
}

/* ==========================================================================
   2. Base
   ========================================================================== */
*, *::before, *::after { box-sizing: border-box; }
html { -webkit-text-size-adjust: 100%; scroll-behavior: smooth; }
body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font-family: var(--font);
  font-size: 1rem;
  line-height: 1.7;
  transition: background-color .25s ease, color .25s ease;
}
img { max-width: 100%; height: auto; display: block; }
a { color: inherit; text-decoration: none; }
a:hover { color: var(--brand-strong); }
button { font: inherit; color: inherit; background: none; border: 0; cursor: pointer; }
:focus-visible { outline: 2px solid var(--brand); outline-offset: 2px; border-radius: 6px; }
.container { width: 100%; max-width: var(--container); margin-inline: auto; padding-inline: 16px; }
.visually-hidden { position: absolute !important; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }
.section, .widget, .widget-content { margin: 0; }

.section-title {
  display: flex; align-items: center; gap: 10px;
  margin: 0 0 16px; font-size: 1.25rem; font-weight: 800;
}
.section-title::before {
  content: ''; width: 6px; height: 22px; border-radius: 4px; background: var(--brand); box-shadow: var(--brand-glow);
}

/* ==========================================================================
   3. Header (sticky, glass) - RTL: logo right, nav center, toggle left
   ========================================================================== */
.site-header {
  position: sticky; top: 0; z-index: 50;
  background: var(--surface-glass);
  -webkit-backdrop-filter: saturate(160%) blur(14px);
  backdrop-filter: saturate(160%) blur(14px);
  border-bottom: 1px solid var(--border);
}
.header-inner {
  height: var(--header-h);
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  gap: 16px;
}
.logo {
  justify-self: start;
  display: inline-flex; align-items: center; gap: 10px;
  font-weight: 800; font-size: 1.35rem; letter-spacing: .3px;
  direction: ltr; white-space: nowrap;
}
.logo__mark {
  width: 36px; height: 36px; display: grid; place-items: center;
  border-radius: 10px; background: var(--brand); color: var(--brand-ink);
  font-size: .95rem; box-shadow: var(--brand-glow);
}
/* Brand logo image: crisp rounded square, never stretched; 40px desktop / 32px mobile */
.logo__mark--img {
  display: block; flex-shrink: 0; width: 40px; height: 40px;
  object-fit: cover; border-radius: 10px; background: #0d4a37;
  box-shadow: 0 0 0 1px rgba(255, 255, 255, .06), 0 4px 14px -4px rgba(50, 205, 50, .45);
}
@media (max-width: 860px) { .logo__mark--img { width: 32px; height: 32px; border-radius: 8px; } }
.logo__text { line-height: 1; }
.logo__text b { color: var(--brand-strong); }
[data-theme="dark"] .logo__text b { color: var(--brand); }

/* --------------------------------------------------------------------------
   Header brand: ambient "matchday broadcast" motion (pure CSS, header only).
   .logo__badge  = fixed-size box (same 40/32px as the image: no layout shift)
     ::before    = emerald aura behind the icon, breathing (opacity + transform)
   .logo__clip   = rounded overflow:hidden frame
     ::after     = diagonal floodlight sheen sweeping across every 5.6s
   League b::after = thin broadcast underline that wipes in on the same beat
   Only transform / opacity are animated. The global prefers-reduced-motion
   rule (and the block below) switches every loop off.
   -------------------------------------------------------------------------- */
.site-header .logo { -webkit-tap-highlight-color: transparent; transition: transform .35s cubic-bezier(.34, 1.56, .64, 1); }
.site-header .logo:active { transform: scale(.94); transition-duration: .12s; }
.logo__badge {
  position: relative; isolation: isolate; flex-shrink: 0;
  display: block; width: 40px; height: 40px;
  transition: transform .4s cubic-bezier(.34, 1.56, .64, 1);
}
.logo__badge::before {                   /* breathing aura */
  content: ''; position: absolute; inset: -5px; z-index: -1; border-radius: 14px;
  background: radial-gradient(closest-side, rgba(50, 205, 50, .55), rgba(16, 122, 84, .25) 60%, transparent);
  filter: blur(4px);
  opacity: .35; transform: scale(.9);
  animation: pxl-logo-aura 3.2s ease-in-out infinite;
  will-change: transform, opacity;
  pointer-events: none;
}
.logo__clip {
  position: relative; display: block; width: 100%; height: 100%;
  border-radius: 10px; overflow: hidden;
  box-shadow: 0 0 0 1px rgba(255, 255, 255, .06), 0 4px 14px -4px rgba(50, 205, 50, .45);
  transform: translateZ(0);              /* own layer: keeps the clip crisp while the sheen moves */
}
.logo__clip .logo__mark--img { width: 100%; height: 100%; border-radius: 0; box-shadow: none; }
.logo__clip::after {                     /* floodlight sheen */
  content: ''; position: absolute; inset: -20% -60%;
  background: linear-gradient(105deg, transparent 38%, rgba(255, 255, 255, .08) 44%, rgba(255, 255, 255, .55) 50%, rgba(214, 255, 226, .12) 56%, transparent 62%);
  transform: translateX(-75%);
  animation: pxl-logo-sheen 5.6s cubic-bezier(.45, 0, .2, 1) infinite;
  will-change: transform;
  pointer-events: none;
}
.site-header .logo__text b { position: relative; display: inline-block; }
.site-header .logo__text b::after {      /* broadcast underline accent */
  content: ''; position: absolute; left: 0; right: 0; bottom: -5px; height: 2px; border-radius: 2px;
  background: linear-gradient(90deg, transparent, var(--brand) 25%, var(--brand) 75%, transparent);
  box-shadow: 0 0 6px var(--brand);
  transform-origin: left center; transform: scaleX(0); opacity: 0;
  animation: pxl-logo-underline 5.6s cubic-bezier(.45, 0, .2, 1) infinite;
  will-change: transform, opacity;
}
@keyframes pxl-logo-aura {
  0%, 100% { opacity: .3;  transform: scale(.9); }
  50%      { opacity: .85; transform: scale(1.08); }
}
@keyframes pxl-logo-sheen {               /* ~1s sweep, then rest */
  0%        { transform: translateX(-75%); }
  18%, 100% { transform: translateX(75%); }
}
@keyframes pxl-logo-underline {
  0%, 8%    { transform: scaleX(0); opacity: 0; }
  22%       { transform: scaleX(1); opacity: 1; }
  60%       { transform: scaleX(1); opacity: .9; }
  80%, 100% { transform: scaleX(1); opacity: 0; }
}
@media (hover: hover) and (pointer: fine) {
  .site-header .logo:hover .logo__badge { transform: translateY(-1px) rotate(-4deg) scale(1.06); }
  .site-header .logo:hover .logo__text b { color: var(--brand); }
}
@media (max-width: 860px) {
  .logo__badge { width: 32px; height: 32px; }
  .logo__clip { border-radius: 8px; }
  .logo__badge::before { inset: -4px; border-radius: 12px; }
}
@media (prefers-reduced-motion: reduce) {
  .logo__badge::before, .logo__clip::after, .site-header .logo__text b::after { animation: none; }
  .logo__badge::before { opacity: .45; transform: none; }
  .logo__clip::after, .site-header .logo__text b::after { opacity: 0; }
}

.main-nav ul { list-style: none; margin: 0; padding: 0; display: flex; gap: 4px; }
.main-nav a {
  display: block; padding: 8px 14px; border-radius: 999px;
  font-weight: 700; font-size: .95rem; color: var(--text-muted);
  transition: color .2s, background-color .2s;
}
.main-nav a:hover, .main-nav a.is-active { color: var(--text); background: var(--brand-soft); }

.header-actions { justify-self: end; display: flex; align-items: center; gap: 6px; }
.icon-btn {
  width: 44px; height: 44px; display: grid; place-items: center;
  border-radius: 12px; border: 1px solid var(--border);
  background: var(--surface); color: var(--text);
  transition: border-color .2s, box-shadow .2s, transform .1s;
}
.icon-btn:hover { border-color: var(--brand); box-shadow: var(--brand-glow); }
.icon-btn:active { transform: scale(.96); }
.icon-btn svg { width: 20px; height: 20px; }
.icon-sun { display: none; }
[data-theme="dark"] .icon-sun { display: block; }
[data-theme="dark"] .icon-moon { display: none; }
.menu-toggle { display: none; }

@media (max-width: 860px) {
  .header-inner { grid-template-columns: 1fr auto; }
  .menu-toggle { display: grid; }
  .main-nav {
    position: fixed; inset: var(--header-h) 0 auto 0;
    background: var(--surface); border-bottom: 1px solid var(--border); box-shadow: var(--shadow);
    padding: 10px 16px 16px;
    max-height: calc(100vh - var(--header-h)); max-height: calc(100dvh - var(--header-h));
    overflow-y: auto; overscroll-behavior: contain; -webkit-overflow-scrolling: touch;
    transform: translateY(-8px); opacity: 0; visibility: hidden;
    transition: opacity .2s, transform .2s, visibility .2s;
  }
  .main-nav.is-open { opacity: 1; transform: none; visibility: visible; }
  .main-nav ul { flex-direction: column; gap: 2px; }
  .main-nav a { padding: 12px 14px; border-radius: var(--radius-sm); font-size: 1rem; }
}

/* ==========================================================================
   4. HOME: Today's matches (rendered by fetchMatches(), grouped by league)
   ========================================================================== */
.fixtures { padding-block: 24px 8px; }
.fixtures-head {
  display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 10px;
  margin-bottom: 18px;
}
.fixtures-head .section-title { margin: 0; font-size: 1.45rem; }
/* Thick lime accent bar on the right (inline-start in RTL) */
.fixtures-head .section-title::before { width: 7px; height: 30px; }
.fixtures-date { color: var(--text-muted); font-weight: 700; font-size: .92rem; }

/* League groups */
.league-group { margin-bottom: 26px; }
.league-group:last-child { margin-bottom: 0; }
.league-group__title {
  display: flex; align-items: center; gap: 10px;
  margin: 0 0 12px; font-size: 1.02rem; font-weight: 800;
}
.league-group__logo { width: 24px; height: 24px; object-fit: contain; }
.league-group__count {
  margin-inline-start: auto;
  padding: 2px 10px; border-radius: 999px;
  background: var(--surface); border: 1px solid var(--border);
  font-size: .75rem; font-weight: 700; color: var(--text-muted);
}
.match-list { display: grid; grid-template-columns: 1fr; gap: 14px; }
@media (min-width: 760px) { .match-list { grid-template-columns: repeat(2, minmax(0, 1fr)); } }

/* "عرض المزيد": always dark with the lime accent (same family as the league filter) */
.load-more-wrap { display: flex; justify-content: center; margin-top: 18px; }
.load-more-wrap[hidden] { display: none; }            /* display:flex would otherwise beat [hidden] */
.load-more {
  display: inline-flex; align-items: center; gap: 8px;
  min-height: 44px; padding: 10px 28px; border-radius: 999px;
  background: #0f172a; border: 1px solid #334155; color: #e2e8f0;
  font: inherit; font-size: .95rem; font-weight: 800; cursor: pointer;
  box-shadow: 0 6px 18px rgba(2, 6, 23, .25);
  transition: border-color .2s, color .2s, box-shadow .2s, transform .15s;
}
.load-more__count { color: #32CD32; font-size: .85rem; direction: ltr; unicode-bidi: isolate; }
.load-more:focus-visible { outline: 2px solid #32CD32; outline-offset: 3px; }
.load-more:active { transform: scale(.97); }
@media (hover: hover) and (pointer: fine) {
  .load-more:hover { border-color: #32CD32; color: #fff; box-shadow: 0 0 18px rgba(50, 205, 50, .35); }
}
/* Cards appended by "عرض المزيد" fade in (disabled by the global prefers-reduced-motion rule) */
.match-card--enter { animation: px-fade-in .35s ease both; }

/* Match card: broadcast-style "scoreboard" card.
   Layers: brand-tinted surface + a 3px status accent bar on top (lime = upcoming,
   red = live, neutral = finished) + a soft radial "stage light" behind the centre. */
.match-card {
  --mc-accent: var(--brand);
  --mc-tint: rgba(50, 205, 50, .07);
  position: relative; isolation: isolate;
  display: block;
  background:
    radial-gradient(120% 90% at 50% 0%, var(--mc-tint), transparent 62%),
    linear-gradient(180deg, var(--surface) 0%, var(--surface-2) 140%);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  box-shadow: var(--card-shadow);
  overflow: hidden;
  color: inherit;
  transition: transform .28s cubic-bezier(.2, .8, .2, 1), box-shadow .28s ease, border-color .28s ease;
}
.match-card::before {                    /* status accent bar */
  content: ''; position: absolute; inset: 0 0 auto; height: 3px; z-index: 1;
  background: linear-gradient(90deg, transparent, var(--mc-accent) 30%, var(--mc-accent) 70%, transparent);
  opacity: .9;
}
[data-theme="dark"] .match-card { --mc-tint: rgba(62, 230, 62, .09); }
@media (hover: hover) and (pointer: fine) {
  a.match-card:hover {
    transform: translateY(-4px); color: inherit;
    border-color: rgba(50, 205, 50, .55);
    box-shadow: 0 0 0 1px rgba(50, 205, 50, .18), 0 14px 32px -12px rgba(50, 205, 50, .35), var(--shadow-hover);
  }
  a.match-card:hover .team__logo { transform: translateY(-2px) scale(1.04); }
  a.match-card:hover .match-card__more { color: var(--brand-strong); gap: 8px; }
}
a.match-card:focus-visible { outline-offset: 3px; border-radius: var(--radius); }

.match-card__top {                       /* league right, round left (RTL) */
  display: flex; align-items: center; justify-content: space-between; gap: 10px;
  padding: 11px 16px 9px;
  border-bottom: 1px solid var(--border);
  font-size: .8rem; font-weight: 700; color: var(--text-muted);
}
.match-card__league {
  display: inline-flex; align-items: center; gap: 8px; min-width: 0;
  color: var(--text); overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
.match-card__league::before {            /* small accent diamond before the competition */
  content: ''; flex-shrink: 0; width: 7px; height: 7px; border-radius: 2px; transform: rotate(45deg);
  background: var(--mc-accent); box-shadow: 0 0 8px var(--mc-accent);
}
.match-card__round {
  flex-shrink: 0; padding: 2px 9px; border-radius: 999px;
  background: var(--surface-2); border: 1px solid var(--border); font-size: .72rem;
}
.match-card__round:empty { display: none; }

.match-card__body {                      /* Team 1 right | center | Team 2 left (RTL) */
  display: flex; align-items: center; justify-content: space-between; gap: 12px;
  padding: 20px 16px 18px;
}
.team {
  flex: 1 1 0; min-width: 0;
  display: flex; flex-direction: column; align-items: center; gap: 9px; text-align: center;
}
.team__logo {                            /* crest pedestal: soft halo + ring, logo itself untouched */
  position: relative;
  width: 60px; height: 60px; border-radius: 50%;
  display: grid; place-items: center;
  background: radial-gradient(circle at 50% 35%, var(--surface) 0%, var(--surface-2) 72%);
  border: 1px solid var(--border);
  box-shadow: inset 0 -6px 14px rgba(0, 0, 0, .06), 0 6px 16px -8px rgba(0, 0, 0, .35);
  overflow: hidden;
  transition: transform .28s cubic-bezier(.2, .8, .2, 1);
}
[data-theme="dark"] .team__logo { box-shadow: inset 0 -6px 14px rgba(0, 0, 0, .35), 0 0 0 3px rgba(255, 255, 255, .02), 0 8px 18px -8px rgba(0, 0, 0, .7); }
.team__initials { font-weight: 800; font-size: .9rem; color: var(--text-muted); }
.team__logo img {
  position: absolute; inset: 0; margin: auto;
  width: 42px; height: 42px; object-fit: contain;     /* never stretched or cropped */
  background: transparent;
}
.team__name { font-weight: 800; font-size: .95rem; line-height: 1.4; max-width: 100%; overflow-wrap: anywhere; }

.match-center { flex: 0 0 auto; display: flex; flex-direction: column; align-items: center; gap: 8px; min-width: 100px; }
.match-time,
.match-score {
  font-variant-numeric: tabular-nums; font-feature-settings: 'tnum' 1;
  font-weight: 800; line-height: 1.15;
  border-radius: 12px; border: 1px solid var(--border);
  background: linear-gradient(180deg, var(--surface) 0%, var(--surface-2) 100%);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, .06), 0 4px 12px -6px rgba(0, 0, 0, .3);
}
.match-time {                            /* kickoff: a scoreboard clock in a lime frame */
  direction: ltr; font-size: 1.45rem; letter-spacing: 1px; padding: 5px 14px;
  border-color: rgba(50, 205, 50, .4);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, .06), 0 0 0 3px var(--brand-soft), 0 6px 16px -8px rgba(50, 205, 50, .45);
}
.match-score {
  /* Flex follows the page direction: first number = Team 1, on Team 1's side */
  display: inline-flex; align-items: center; gap: 10px;
  font-size: 1.6rem; padding: 4px 16px;
}
.match-score .sep { color: var(--text-muted); font-weight: 600; font-size: 1.1rem; }

/* Status badges: one pill shape for every state */
.badge {
  display: inline-flex; align-items: center; gap: 6px;
  padding: 3px 11px; border-radius: 999px;
  font-size: .74rem; font-weight: 800; white-space: nowrap;
  background: var(--surface-2); color: var(--text-muted); border: 1px solid var(--border);
}
.badge--upcoming { background: var(--brand-soft); color: var(--brand-strong); border-color: rgba(50, 205, 50, .3); }
[data-theme="dark"] .badge--upcoming { color: var(--brand); }
.badge--upcoming::before {               /* tiny clock face */
  content: ''; width: 9px; height: 9px; border-radius: 50%; box-sizing: border-box;
  border: 1.6px solid currentColor;
  background: linear-gradient(currentColor, currentColor) 50% 18% / 1.4px 3.4px no-repeat;
}
.badge--finished::before { content: '\2713'; font-size: .72rem; line-height: 1; }
.badge--live { background: var(--live-soft); color: var(--live); border-color: rgba(225, 29, 72, .35); }
.badge--live::before {
  content: ''; width: 7px; height: 7px; border-radius: 50%; background: var(--live);
  animation: pxl-pulse 1.6s infinite;
}

/* States: same design language, different accent */
.match-card--live {
  --mc-accent: var(--live); --mc-tint: rgba(225, 29, 72, .09);
  border-color: rgba(225, 29, 72, .35);
  box-shadow: 0 0 0 1px rgba(225, 29, 72, .10), 0 10px 28px -14px rgba(225, 29, 72, .5), var(--card-shadow);
}
.match-card--live::before { animation: mc-breathe 2.4s ease-in-out infinite; }
.match-card--live .match-score { color: var(--live); border-color: rgba(225, 29, 72, .35); box-shadow: 0 0 0 3px var(--live-soft), 0 6px 16px -8px rgba(225, 29, 72, .5); }
@keyframes mc-breathe { 0%, 100% { opacity: .5; } 50% { opacity: 1; } }
.match-card--finished { --mc-accent: var(--text-muted); --mc-tint: transparent; }
.match-card--finished::before { opacity: .35; }

/* Footer: coverage chips. Known commentator / channel = solid chip; unknown = quiet
   dashed "يُعلن لاحقًا" chip before kickoff, left out once the match has started;
   nothing to show = only the "التفاصيل" hint. */
.match-card__bottom {
  display: flex; flex-wrap: wrap; align-items: center; gap: 8px;
  padding: 10px 16px 12px;
  border-top: 1px solid var(--border);
  font-size: .78rem; color: var(--text-muted);
}
.match-card__meta {
  display: inline-flex; align-items: center; gap: 6px; min-width: 0; max-width: 100%;
  padding: 4px 10px; border-radius: 999px;
  background: var(--brand-soft); border: 1px solid rgba(50, 205, 50, .25);
  color: var(--text); font-weight: 700;
}
.match-card__meta span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.match-card__meta svg { width: 14px; height: 14px; flex-shrink: 0; color: var(--brand-strong); }
[data-theme="dark"] .match-card__meta svg { color: var(--brand); }
.match-card__meta--pending {
  background: transparent; border-style: dashed; border-color: var(--border);
  color: var(--text-muted); font-weight: 600;
}
.match-card__meta--pending svg { color: var(--text-muted); opacity: .8; }
[data-theme="dark"] .match-card__meta--pending svg { color: var(--text-muted); }
.match-card__more {
  margin-inline-start: auto; display: inline-flex; align-items: center; gap: 5px;
  font-weight: 800; font-size: .76rem; color: var(--text-muted); transition: color .2s, gap .2s;
}

/* Loading / error / empty */
.px-loader {
  display: grid; justify-items: center; gap: 14px;
  padding: 48px 16px; color: var(--text-muted); font-weight: 700;
}
.px-spinner {
  width: 44px; height: 44px; border-radius: 50%;
  border: 4px solid var(--surface-2); border-top-color: var(--brand);
  animation: px-spin .8s linear infinite;
}
@keyframes px-spin { to { transform: rotate(360deg); } }
.match-message {
  display: grid; justify-items: center; gap: 12px;
  padding: 32px 16px; text-align: center; color: var(--text-muted);
  background: var(--surface); border: 1px dashed var(--border); border-radius: var(--radius);
}
.px-retry {
  min-height: 44px; padding: 8px 20px; border-radius: 999px;
  background: var(--brand); color: var(--brand-ink); font-weight: 800;
  box-shadow: var(--brand-glow);
}
.px-retry:hover { background: var(--brand-strong); }

/* opacity/transform only: runs on the compositor, no per-frame repaint (box-shadow did) */
@keyframes pxl-pulse {
  0%, 100% { opacity: 1; transform: scale(1); }
  50% { opacity: .35; transform: scale(.7); }
}

/* ==========================================================================
   5. MATCH POST: streaming arena (16:9 player + ads)
   ========================================================================== */
.arena { padding-block: 20px 4px; }
.arena-head { display: flex; flex-wrap: wrap; align-items: center; gap: 10px 14px; margin-bottom: 12px; }
.arena-title { margin: 0; font-size: 1.35rem; line-height: 1.45; font-weight: 800; }
.live-pill {
  display: inline-flex; align-items: center; gap: 8px;
  padding: 4px 12px; border-radius: 999px;
  background: var(--live-soft); color: var(--live); font-weight: 800; font-size: .85rem;
}
.live-pill::before { content: ''; width: 8px; height: 8px; border-radius: 50%; background: var(--live); animation: pxl-pulse 1.6s infinite; }

.arena-grid { display: grid; grid-template-columns: 1fr; gap: 16px; align-items: start; }
.arena-center { min-width: 0; display: grid; gap: 14px; }

.player-frame {
  position: relative; width: 100%; aspect-ratio: 16 / 9;
  width: min(100%, calc((100vh - var(--header-h) - 24px) * 16 / 9));
  width: min(100%, calc((100svh - var(--header-h) - 24px) * 16 / 9));
  margin-inline: auto; contain: layout paint;
  border-radius: var(--radius); overflow: hidden; background: #000;
  box-shadow: var(--shadow); border: 1px solid var(--border);
}
[data-theme="dark"] .player-frame { box-shadow: 0 0 0 1px rgba(62, 230, 62, .25), 0 0 40px rgba(62, 230, 62, .12); }
@supports not (aspect-ratio: 16 / 9) { .player-frame { height: 0; padding-top: 56.25%; } }
.player-frame iframe, .player-frame video, .player-placeholder {
  position: absolute; inset: 0; width: 100%; height: 100%; border: 0;
}
.player-placeholder {
  display: grid; place-items: center; align-content: center; gap: 10px; text-align: center;
  color: #cfd6dd; font-weight: 700;
  background: radial-gradient(ellipse at center, #10161d 0%, #000 75%);
}
.player-placeholder svg { width: 54px; height: 54px; color: var(--brand); filter: drop-shadow(0 0 12px rgba(50, 205, 50, .5)); }

/* Ad slots (post view only). Hidden until BOTH are true:
   - the slot holds real ad code (JS adds .is-filled: an <ins>, <iframe> or <img>), and
   - the arena is ready (JS adds .is-ready after the player iframe has loaded).
   No placeholder boxes, and no ad is ever shown next to an empty player or a loading
   spinner. The adsbygoogle push happens only after the slot became visible. */
.ad-slot {
  display: none; place-items: center; width: 100%;
  overflow: hidden; text-align: center;
}
.ad-slot .widget, .ad-slot .widget-content { width: 100%; display: grid; place-items: center; }
.ad-slot ins.adsbygoogle { display: block; width: 100%; }
.arena.is-ready .ad-slot.is-filled { display: grid; min-height: 100px; }   /* 320x100 mobile */
@media (min-width: 768px) { .arena.is-ready .ad-slot.is-filled { min-height: 90px; } }   /* 728x90 */

/* ==========================================================================
   6. Content + sidebar
   ========================================================================== */
.content-wrap { display: grid; grid-template-columns: 1fr; gap: 24px; padding-block: 24px 40px; }
@media (min-width: 1024px) { .content-wrap { grid-template-columns: minmax(0, 1fr) 320px; } }

/* Post cards (home "latest", label & search pages) */
.post-grid { display: grid; grid-template-columns: 1fr; gap: 18px; }
@media (min-width: 600px) { .post-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
@media (min-width: 1280px) { .post-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); } }
.card {
  display: flex; flex-direction: column;
  background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius);
  overflow: hidden; box-shadow: var(--shadow);
  transition: transform .25s ease, box-shadow .25s ease, border-color .25s ease;
}
@media (hover: hover) and (pointer: fine) {
  .card:hover { transform: translateY(-4px); box-shadow: var(--shadow-hover); border-color: var(--brand); }
  .card:hover .card__media img { transform: scale(1.05); }
}
.card__media { position: relative; display: block; aspect-ratio: 16 / 9; overflow: hidden; background: var(--surface-2); }
.card__media img { width: 100%; height: 100%; object-fit: cover; transition: transform .45s ease; }
.card__placeholder { position: absolute; inset: 0; display: grid; place-items: center; font-size: 2rem; font-weight: 800; color: var(--brand); direction: ltr; }
.card__body { display: flex; flex-direction: column; gap: 8px; padding: 14px 16px 16px; flex: 1; }
.card__tag {
  align-self: flex-start; padding: 2px 10px; border-radius: 999px;
  background: var(--brand-soft); color: var(--brand-strong); font-size: .78rem; font-weight: 800;
}
[data-theme="dark"] .card__tag { color: var(--brand); }
.card__title { margin: 0; font-size: 1.05rem; line-height: 1.5; font-weight: 800; }
.card__excerpt {
  margin: 0; color: var(--text-muted); font-size: .92rem;
  display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden;
}
.card__date { margin-top: auto; color: var(--text-muted); font-size: .8rem; }
.empty-state { padding: 40px 16px; text-align: center; color: var(--text-muted); background: var(--surface); border: 1px dashed var(--border); border-radius: var(--radius); }
.pager { display: flex; justify-content: space-between; gap: 12px; margin-top: 24px; }
.pager a {
  display: inline-flex; align-items: center; gap: 8px; padding: 10px 18px; border-radius: 999px;
  background: var(--surface); border: 1px solid var(--border); font-weight: 700; box-shadow: var(--shadow);
}
.pager a:hover { border-color: var(--brand); color: var(--text); box-shadow: var(--brand-glow); }

/* Article cover image (first block of every news post body: <div class="post-cover">) */
.post-body .post-cover { margin: 0 0 20px; }
.post-body .post-cover img { display: block; width: 100%; height: auto; aspect-ratio: 16 / 9; object-fit: cover; border-radius: var(--radius-sm); }

/* Home sidebar: "أحدث الأخبار" card (7 latest posts, rendered by the Blog widget and
   moved into #home-news-slot). The sidebar stops being sticky on the home page:
   with this card it is taller than the viewport. */
.home-news { background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius); padding: 16px; box-shadow: var(--shadow); }
.home-news__title { margin: 0 0 12px; font-size: 1.05rem; font-weight: 800; display: flex; align-items: center; gap: 8px; }
.home-news__title::before { content: ''; width: 4px; height: 18px; border-radius: 3px; background: var(--brand); }
.home-news__list { list-style: none; margin: 0; padding: 0; display: grid; }
.home-news__item { display: grid; grid-template-columns: 104px minmax(0, 1fr); gap: 12px; align-items: start; padding: 10px 0; border-top: 1px solid var(--border); }
.home-news__item:first-child { border-top: 0; padding-top: 0; }
.home-news__thumb { position: relative; display: block; aspect-ratio: 16 / 9; border-radius: var(--radius-sm); overflow: hidden; background: var(--surface-2); }
.home-news__thumb img { width: 100%; height: 100%; object-fit: cover; }
.home-news__thumb .card__placeholder { font-size: 1rem; }
.home-news__body { display: flex; flex-direction: column; gap: 4px; min-width: 0; }
.home-news__item-title { margin: 0; font-size: .9rem; line-height: 1.55; font-weight: 700;
  display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.home-news__item-title a { color: var(--text); }
.home-news__item-title a:hover { color: var(--brand-strong); }
.home-news__meta { display: flex; flex-wrap: wrap; align-items: center; gap: 6px; color: var(--text-muted); font-size: .75rem; }
.home-news__meta .card__tag { font-size: .7rem; padding: 1px 8px; }
.home-news__empty { margin: 0 0 12px; color: var(--text-muted); font-size: .88rem; }
.btn-all-news {
  display: flex; align-items: center; justify-content: center; gap: 8px; min-height: 44px; margin-top: 14px;
  border-radius: 999px; background: var(--brand); color: var(--brand-ink); font-weight: 800; box-shadow: var(--brand-glow);
}
.btn-all-news:hover { background: var(--brand-strong); color: var(--brand-ink); }
@media (min-width: 1024px) { .sidebar:has(#home-news) { position: static; } }

/* News archive page (/p/news.html) */
.news-page__head { margin-bottom: 4px; }
.news-page__status { margin: 0 0 14px; color: var(--text-muted); font-size: .88rem; }
.news-pager { display: flex; flex-wrap: wrap; justify-content: center; align-items: center; gap: 8px; margin-top: 28px; }
.news-pager a, .news-pager span {
  display: inline-grid; place-items: center; min-width: 44px; min-height: 44px; padding: 0 14px; border-radius: 999px;
  background: var(--surface); border: 1px solid var(--border); font-weight: 700; box-shadow: var(--shadow);
}
.news-pager a:hover { border-color: var(--brand); color: var(--text); box-shadow: var(--brand-glow); }
.news-pager [aria-current='page'] { background: var(--brand); border-color: var(--brand); color: var(--brand-ink); }
.news-pager .news-pager__gap { background: none; border: 0; box-shadow: none; min-width: 20px; padding: 0; }

/* Post / page article */
.post-full { background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius); padding: 22px; box-shadow: var(--shadow); }
.post-full__title { margin: 0 0 6px; font-size: 1.5rem; line-height: 1.45; font-weight: 800; }
.post-meta { color: var(--text-muted); font-size: .88rem; margin-bottom: 18px; }
.post-body { font-size: 1.02rem; overflow-wrap: anywhere; }
.post-body img { border-radius: var(--radius-sm); margin-inline: auto; }
.post-body a { color: var(--brand-strong); text-decoration: underline; text-underline-offset: 3px; }
[data-theme="dark"] .post-body a { color: var(--brand); }
.post-body iframe { max-width: 100%; }
.post-body pre { max-width: 100%; overflow-x: auto; -webkit-overflow-scrolling: touch; direction: ltr; }
.post-body [data-stream-src] { display: none; }
/* Standard article typography */
.post-full__title[hidden] { display: none; }
.post-meta { display: flex; flex-wrap: wrap; align-items: center; gap: 6px; }
.post-meta__sep { opacity: .6; }
.post-body { line-height: 1.95; }
.post-body > :first-child { margin-top: 0; }
.post-body p { margin: 0 0 1.1em; }
.post-body h2, .post-body h3, .post-body h4 { margin: 1.6em 0 .6em; line-height: 1.5; font-weight: 800; }
.post-body h2 { font-size: 1.3rem; padding-inline-start: 12px; border-inline-start: 4px solid var(--brand); }
.post-body h3 { font-size: 1.12rem; }
.post-body h4 { font-size: 1rem; }
.post-body ul, .post-body ol { margin: 0 0 1.1em; padding-inline-start: 1.4em; }
.post-body li { margin-bottom: .35em; }
.post-body li::marker { color: var(--brand-strong); }
.post-body blockquote {
  margin: 1.4em 0; padding: 14px 18px; border-radius: var(--radius-sm);
  background: var(--surface-2); border-inline-start: 4px solid var(--brand); color: var(--text);
}
.post-body table { width: 100%; border-collapse: collapse; margin: 1.2em 0; font-size: .95rem; display: block; overflow-x: auto; }
.post-body th, .post-body td { padding: 10px 12px; border: 1px solid var(--border); text-align: start; }
.post-body th { background: var(--surface-2); font-weight: 800; }
.post-body .tr-caption-container { display: table; margin: 1.2em auto; }
.post-body .tr-caption { font-size: .85rem; color: var(--text-muted); padding-top: 6px; }
.post-body hr { border: 0; height: 1px; background: var(--border); margin: 2em 0; }
.post-body code { padding: 2px 6px; border-radius: 6px; background: var(--surface-2); font-size: .9em; direction: ltr; unicode-bidi: isolate; }
.post-body iframe, .post-body video { display: block; width: 100%; aspect-ratio: 16 / 9; height: auto; border: 0; border-radius: var(--radius-sm); margin: 1.2em 0; }
.empty-state--404 { display: grid; justify-items: center; gap: 10px; padding: 56px 16px; }
.empty-state--404 strong { font-size: 3rem; line-height: 1; color: var(--brand-strong); }
.empty-state--404 p { margin: 0; }
.empty-state--404 .px-retry { text-decoration: none; }

/* ============================ Match details page ============================ */
.match-page { display: grid; gap: 16px; }
.match-hero {
  position: relative; overflow: hidden;
  border-radius: var(--radius); border: 1px solid #1f2937;
  background:
    radial-gradient(120% 90% at 50% -10%, rgba(50, 205, 50, .18), transparent 60%),
    linear-gradient(165deg, #0b1220 0%, #0f172a 55%, #0b1a10 100%);
  color: #f1f5f9; box-shadow: 0 18px 40px rgba(2, 6, 23, .35);
  min-height: 240px;
}
.match-hero .px-loader, .match-hero .match-message { color: #cbd5e1; min-height: 240px; }
.mh__league {
  display: flex; align-items: center; justify-content: center; flex-wrap: wrap; gap: 8px 10px;
  padding: 14px 16px 0; font-size: .85rem; font-weight: 700; color: #94a3b8; text-align: center;
}
.mh__league img { width: 22px; height: 22px; object-fit: contain; }
.mh__league b { color: #e2e8f0; }
.mh__teams { display: grid; grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr); align-items: center; gap: 12px; padding: 22px 16px 14px; }
.mh__team { display: grid; justify-items: center; gap: 10px; text-align: center; min-width: 0; }
.mh__logo {
  width: 84px; height: 84px; border-radius: 50%; display: grid; place-items: center;
  background: rgba(255, 255, 255, .06); border: 1px solid rgba(255, 255, 255, .12);
  box-shadow: 0 0 0 6px rgba(255, 255, 255, .02);
}
.mh__logo img { width: 58px; height: 58px; object-fit: contain; }
.mh__logo span { font-weight: 800; color: #94a3b8; }
.mh__name { font-size: 1.05rem; font-weight: 800; line-height: 1.4; overflow-wrap: anywhere; }
.mh__center { display: grid; justify-items: center; gap: 10px; min-width: 120px; }
.mh__score { display: inline-flex; align-items: center; gap: 12px; font-size: 2.6rem; font-weight: 900; line-height: 1; letter-spacing: 1px; }
.mh__score .sep { color: #475569; font-size: 1.8rem; }
.match-hero--live .mh__score { color: #32CD32; text-shadow: 0 0 22px rgba(50, 205, 50, .35); }
.mh__time { direction: ltr; font-size: 2rem; font-weight: 900; padding: 4px 16px; border-radius: 12px; background: rgba(255, 255, 255, .06); }
.mh__badge { display: inline-flex; align-items: center; gap: 6px; padding: 3px 12px; border-radius: 999px; font-size: .78rem; font-weight: 800; background: rgba(255, 255, 255, .08); color: #cbd5e1; }
.mh__badge--live { background: rgba(255, 59, 92, .16); color: #ff5c78; }
.mh__badge--live::before { content: ''; width: 7px; height: 7px; border-radius: 50%; background: #ff3b5c; animation: pxl-pulse 1.6s infinite; }
.mh__ht { font-size: .8rem; color: #94a3b8; }
.mh__meta {
  list-style: none; margin: 0; padding: 12px 16px 16px;
  display: flex; flex-wrap: wrap; justify-content: center; gap: 8px;
  border-top: 1px solid rgba(255, 255, 255, .06);
}
.mh__meta li {
  display: inline-flex; align-items: center; gap: 6px; max-width: 100%; min-width: 0;
  padding: 5px 12px; border-radius: 999px; font-size: .8rem; font-weight: 700;
  background: rgba(255, 255, 255, .05); border: 1px solid rgba(255, 255, 255, .07); color: #cbd5e1;
}
.mh__meta svg { width: 15px; height: 15px; color: #32CD32; flex: 0 0 auto; }
@media (max-width: 520px) {
  .mh__logo { width: 64px; height: 64px; } .mh__logo img { width: 44px; height: 44px; }
  .mh__name { font-size: .92rem; } .mh__score { font-size: 2rem; } .mh__time { font-size: 1.5rem; }
  .mh__center { min-width: 92px; }
}

.match-tabs {
  display: flex; gap: 6px; padding: 6px; border-radius: 999px;
  background: #0f172a; border: 1px solid #334155; position: sticky; top: calc(var(--header-h) + 6px); z-index: 5;
}
.match-tab {
  flex: 1 1 0; min-height: 44px; padding: 10px 14px; border: 0; border-radius: 999px; cursor: pointer;
  background: transparent; color: #cbd5e1; font: inherit; font-weight: 800; font-size: .92rem;
  transition: background-color .2s, color .2s, box-shadow .2s;
}
.match-tab:hover { color: #fff; }
.match-tab.is-active { background: #32CD32; color: #04120a; box-shadow: 0 0 16px rgba(50, 205, 50, .4); }
.match-tab:focus-visible { outline: 2px solid #32CD32; outline-offset: 2px; }
.match-panel { background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius); box-shadow: var(--shadow); padding: 16px; min-height: 180px; animation: px-fade-in .3s ease both; }
.match-panel[hidden] { display: none; }
.match-panel .match-message { padding: 40px 12px; }

/* Events timeline: home side | minute | away side (RTL: home on the right) */
.ev-list { list-style: none; margin: 0; padding: 0; position: relative; }
.ev-list::before { content: ''; position: absolute; inset-block: 0; inset-inline-start: 50%; width: 2px; transform: translateX(50%); background: var(--border); }
.ev { position: relative; display: grid; grid-template-columns: minmax(0, 1fr) 54px minmax(0, 1fr); align-items: center; gap: 10px; padding: 7px 0; }
.ev__min {
  grid-column: 2; justify-self: center; z-index: 1;
  min-width: 46px; padding: 3px 6px; border-radius: 999px; text-align: center;
  background: var(--surface-2); border: 1px solid var(--border); font-size: .78rem; font-weight: 800;
}
.ev__body { display: flex; align-items: center; gap: 10px; min-width: 0; padding: 8px 12px; border-radius: 12px; background: var(--surface-2); }
.ev--home .ev__body { grid-column: 1; grid-row: 1; justify-self: end; flex-direction: row-reverse; text-align: end; }
.ev--away .ev__body { grid-column: 3; grid-row: 1; justify-self: start; }
.ev__icon { flex: 0 0 auto; width: 28px; height: 28px; border-radius: 50%; display: grid; place-items: center; background: var(--surface); }
.ev__icon svg { width: 16px; height: 16px; }
.ev__txt { display: grid; gap: 2px; min-width: 0; }
.ev__txt b { font-size: .9rem; overflow-wrap: anywhere; }
.ev__txt small { color: var(--text-muted); font-size: .76rem; }
.ev--goal .ev__body { background: rgba(50, 205, 50, .12); box-shadow: inset 0 0 0 1px rgba(50, 205, 50, .35); }
.ev--goal .ev__icon { color: var(--brand-strong); }
.ev__in { color: #16a34a; } .ev__out { color: #e11d48; }
.card-ico { display: inline-block; width: 11px; height: 15px; border-radius: 2px; }
.card-ico--y { background: #facc15; } .card-ico--r { background: #e11d48; }
.card-ico--yr { background: linear-gradient(135deg, #facc15 50%, #e11d48 50%); }
.ev.ev--period { grid-template-columns: 1fr; }
.ev--period .ev__period {
  justify-self: center; z-index: 1; padding: 5px 14px; white-space: nowrap; border-radius: 999px;
  background: #0f172a; color: #e2e8f0; border: 1px solid #334155; font-size: .78rem; font-weight: 800;
}
.ev--period .ev__period b { color: #32CD32; margin-inline-start: 8px; display: inline-block; }
@media (max-width: 520px) { .ev { grid-template-columns: minmax(0, 1fr) 46px minmax(0, 1fr); gap: 6px; } .ev__body { padding: 6px 8px; gap: 6px; } .ev__icon { width: 24px; height: 24px; } }

/* Lineups */
.lu-grid { display: grid; gap: 16px; grid-template-columns: repeat(auto-fit, minmax(min(100%, 340px), 1fr)); }
.lu-team { display: grid; gap: 12px; align-content: start; }
.lu-head { display: flex; align-items: center; gap: 10px; font-weight: 800; }
.lu-head img { width: 30px; height: 30px; object-fit: contain; }
.lu-formation { margin-inline-start: auto; padding: 3px 10px; border-radius: 999px; background: #0f172a; color: #32CD32; border: 1px solid #334155; font-size: .8rem; direction: ltr; }
.pitch {
  position: relative; display: flex; flex-direction: column-reverse; justify-content: space-between; gap: 10px;
  min-height: 420px; padding: 18px 8px; border-radius: 14px; overflow: hidden;
  background:
    linear-gradient(rgba(255, 255, 255, .14), rgba(255, 255, 255, .14)) center / 100% 2px no-repeat,
    repeating-linear-gradient(0deg, #14532d 0 42px, #166534 42px 84px);
  border: 2px solid rgba(255, 255, 255, .18);
}
.pitch::before { content: ''; position: absolute; left: 50%; top: 50%; width: 90px; height: 90px; border: 2px solid rgba(255, 255, 255, .14); border-radius: 50%; transform: translate(-50%, -50%); }
.pitch__line { position: relative; display: flex; justify-content: space-around; gap: 4px; }
.pl { display: grid; justify-items: center; gap: 4px; flex: 1 1 0; min-width: 0; max-width: 72px; text-align: center; color: #fff; }
.pl__num {
  position: relative; width: 36px; height: 36px; border-radius: 50%; display: grid; place-items: center;
  background: #0f172a; border: 2px solid #32CD32; font-weight: 900; font-size: .85rem;
}
.pl--gk .pl__num { border-color: #facc15; }
.pl__name { font-size: .72rem; font-weight: 800; line-height: 1.3; text-shadow: 0 1px 2px rgba(0, 0, 0, .6); overflow-wrap: anywhere; }
.pl__tags { display: flex; gap: 3px; justify-content: center; min-height: 14px; }
.pl__rating { position: absolute; top: -8px; inset-inline-end: -14px; padding: 0 4px; border-radius: 6px; font-size: .62rem; font-weight: 800; background: #32CD32; color: #04120a; }
.pl__cap { position: absolute; bottom: -6px; inset-inline-start: -8px; width: 16px; height: 16px; border-radius: 50%; font-size: .6rem; display: grid; place-items: center; background: #facc15; color: #0f172a; font-weight: 900; }
.tag-goal { font-size: .7rem; } .tag-sub { color: #fda4af; font-size: .7rem; }
.lu-sub-title { margin: 4px 0 0; font-size: .92rem; font-weight: 800; }
.lu-list { list-style: none; margin: 0; padding: 0; display: grid; gap: 6px; }
.lu-list li { display: flex; align-items: center; gap: 10px; padding: 8px 10px; border-radius: 10px; background: var(--surface-2); font-size: .88rem; }
.lu-list .n { flex: 0 0 auto; width: 28px; height: 28px; border-radius: 50%; display: grid; place-items: center; background: var(--surface); border: 1px solid var(--border); font-weight: 800; font-size: .78rem; }
.lu-list .meta { margin-inline-start: auto; display: inline-flex; align-items: center; gap: 6px; color: var(--text-muted); font-size: .76rem; }
.lu-list .r { padding: 1px 6px; border-radius: 6px; background: var(--brand-soft); color: var(--brand-strong); font-weight: 800; }
.lu-coach { margin: 0; color: var(--text-muted); font-size: .85rem; }
.lu-coach b { color: var(--text); }
.post-labels { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 20px; }

/* Sidebar */
.sidebar { display: grid; gap: 18px; align-content: start; }
.sidebar .widget { background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius); padding: 16px; box-shadow: var(--shadow); }
.widget-title { margin: 0 0 12px; font-size: 1.02rem; font-weight: 800; display: flex; align-items: center; gap: 8px; }
.widget-title::before { content: ''; width: 4px; height: 18px; border-radius: 3px; background: var(--brand); }
@media (min-width: 1024px) { .sidebar { position: sticky; top: calc(var(--header-h) + 16px); } }
.standings { width: 100%; border-collapse: collapse; font-size: .88rem; }
.standings th, .standings td { padding: 8px 6px; text-align: center; border-bottom: 1px solid var(--border); }
.standings th { color: var(--text-muted); font-weight: 700; font-size: .78rem; }
.standings td:nth-child(2), .standings th:nth-child(2) { text-align: start; }
.standings tr:last-child td { border-bottom: 0; }
.standings .pos { width: 26px; font-weight: 800; }
.standings tr.top .pos { color: var(--brand-strong); }
[data-theme="dark"] .standings tr.top .pos { color: var(--brand); }
.standings .pts { font-weight: 800; }
.standings .team-cell { display: flex; align-items: center; gap: 8px; min-width: 0; }
.standings .team-cell img { width: 20px; height: 20px; object-fit: contain; flex-shrink: 0; }
.standings .team-cell span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.standings .diff { direction: ltr; }
.standings tr.standings-state td { padding: 22px 6px; color: var(--text-muted); font-size: .82rem; }
.px-mini-spinner {
  display: inline-block; width: 26px; height: 26px; border-radius: 50%;
  border: 3px solid rgba(50, 205, 50, 0.2); border-top-color: #32CD32;
  animation: px-mini-spin .8s linear infinite;
}
@keyframes px-mini-spin { to { transform: rotate(360deg); } }
/* Standings page */
/* Routed pages: both sections ship hidden on every static page; the route script unhides one. */
.standings-page[hidden], .match-page[hidden] { display: none; }
html[data-pxl-route] #main { display: none !important; }
.standings-page { display: grid; gap: 18px; }
.standings-page__head .section-title { margin-bottom: 4px; }
.standings-page__sub { margin: 0; color: var(--text-muted); font-size: .92rem; }

/* League filter: scrollable pill bar, gradient + glow on the active league */
.league-filter {
  display: flex; gap: 8px; overflow-x: auto; overflow-y: hidden; scroll-snap-type: x proximity;
  -webkit-overflow-scrolling: touch; overscroll-behavior-x: contain;
  padding: 10px; scroll-padding-inline: 10px; border-radius: calc(var(--radius) + 4px);
  background: var(--surface); border: 1px solid var(--border); box-shadow: var(--shadow);
  scrollbar-width: none;
}
.league-filter::-webkit-scrollbar { display: none; }
.league-chip {
  position: relative; flex: 0 0 auto; scroll-snap-align: start;
  display: inline-flex; align-items: center; gap: 8px;
  min-height: 44px; padding: 8px 16px; border-radius: 999px;
  border: 1px solid var(--border); background: var(--surface-2); color: var(--text-muted);
  font: inherit; font-size: .88rem; font-weight: 700; white-space: nowrap; cursor: pointer;
  transition: background-color .2s, color .2s, border-color .2s, box-shadow .25s, transform .2s;
}
.league-chip::before {
  content: ''; width: 7px; height: 7px; border-radius: 50%; flex-shrink: 0;
  background: currentColor; opacity: .35; transition: opacity .2s, background-color .2s;
}
.league-chip:hover { color: var(--text); border-color: var(--brand); transform: translateY(-1px); }
.league-chip:hover::before { opacity: .8; background: var(--brand); }
.league-chip:active { transform: scale(.97); }
.league-chip.is-active {
  background: linear-gradient(135deg, var(--brand) 0%, var(--brand-strong) 100%);
  border-color: transparent; color: var(--brand-ink); transform: none;
  box-shadow: 0 0 0 3px var(--brand-soft), 0 6px 20px rgba(50, 205, 50, .38);
}
.league-chip.is-active::before { opacity: 1; background: var(--brand-ink); animation: pxl-chip-dot 1.8s ease-in-out infinite; }
@keyframes pxl-chip-dot { 0%, 100% { box-shadow: 0 0 0 0 rgba(4, 18, 10, .35); } 50% { box-shadow: 0 0 0 4px rgba(4, 18, 10, 0); } }
.league-chip:focus-visible { outline: 2px solid var(--brand); outline-offset: 3px; }

.standings-board { min-height: 260px; }
.standings-loading, .standings-message {
  display: grid; justify-items: center; gap: 12px;
  padding: 60px 16px; color: var(--text-muted); font-weight: 700; text-align: center;
}
.standings-board.is-ready .standings-card { animation: px-fade-in .35s ease both; }
@keyframes px-fade-in { from { opacity: 0; transform: translateY(6px); } to { opacity: 1; transform: none; } }

/* Skeleton loader: shimmering rows shaped like the table */
.standings-skeleton {
  --sk-base: var(--border); --sk-shine: rgba(255, 255, 255, .75);
  background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius);
  box-shadow: var(--shadow); overflow: hidden;
}
[data-theme="dark"] .standings-skeleton { --sk-shine: rgba(62, 230, 62, .10); }
.sk-head { display: flex; align-items: center; gap: 10px; padding: 14px 16px; background: var(--surface-2); border-bottom: 1px solid var(--border); }
.sk-row {
  display: grid; grid-template-columns: 26px 24px minmax(0, 1fr) repeat(3, 32px); align-items: center; gap: 12px;
  padding: 13px 16px; border-bottom: 1px solid var(--border);
  animation: px-fade-in .4s ease both; animation-delay: calc(var(--i, 0) * 45ms);
}
.sk-row:last-child { border-bottom: 0; }
.sk {
  display: block; height: 12px; border-radius: 6px; color: transparent; overflow: hidden;
  background: linear-gradient(90deg, transparent 0%, transparent 35%, var(--sk-shine) 50%, transparent 65%, transparent 100%) var(--sk-base);
  background-size: 200% 100%;
  animation: px-shimmer 1.4s ease-in-out infinite;
}
.sk--pos { width: 22px; height: 22px; border-radius: 7px; }
.sk--logo { width: 24px; height: 24px; border-radius: 50%; }
.sk--title { width: 160px; height: 14px; }
.sk--badge { width: 64px; height: 18px; border-radius: 999px; margin-inline-start: auto; }
.sk--num { width: 100%; }
@media (max-width: 640px) {
  .sk-row { grid-template-columns: 22px 22px minmax(0, 1fr) repeat(2, 28px); gap: 10px; }
  .sk--opt { display: none; }
}

/* Standings card + full table */
.standings-card {
  background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius);
  box-shadow: var(--shadow); overflow: hidden; margin-bottom: 16px;
}
.standings-card__head {
  display: flex; align-items: center; gap: 10px;
  padding: 12px 16px; background: var(--surface-2); border-bottom: 1px solid var(--border);
  font-weight: 800;
}
.standings-card__head img { width: 26px; height: 26px; object-fit: contain; }
.standings-card__head small {
  white-space: nowrap; margin-inline-start: auto; padding: 3px 10px; border-radius: 999px;
  background: var(--brand-soft); color: var(--text); font-weight: 700; font-size: .76rem;
}
.standings-scroll { overflow-x: auto; -webkit-overflow-scrolling: touch; overscroll-behavior-x: contain; }
.standings--full { min-width: 100%; font-size: .9rem; font-variant-numeric: tabular-nums; }
.standings--full th, .standings--full td { padding: 10px 8px; white-space: nowrap; }
.standings--full thead th { background: var(--card-head); font-size: .75rem; padding-block: 11px; }
.standings--full td:nth-child(2) { min-width: 150px; }
.standings--full tbody tr {
  transition: background-color .18s ease;
  animation: pxl-row-in .38s cubic-bezier(.2, .7, .2, 1) both; animation-delay: calc(var(--i, 0) * 22ms);
}
@keyframes pxl-row-in { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: none; } }
.standings--full tbody tr[data-zone] { background: color-mix(in srgb, var(--zone) 6%, transparent); }
.standings--full tbody tr:hover { background: var(--brand-soft); }
.standings--full .team-cell img { width: 24px; height: 24px; transition: transform .2s ease; }
.standings--full .team-cell span { transition: color .18s; }
.standings--full tbody tr:hover .team-cell img { transform: scale(1.15); }
.standings--full tbody tr:hover .team-cell span { color: var(--brand-strong); }
[data-theme="dark"] .standings--full tbody tr:hover .team-cell span { color: var(--brand); }
/* Zone: colored bar on the start edge (right in RTL) + tinted rank badge */
.standings--full td.pos { position: relative; width: 44px; }
.standings--full tr[data-zone] td.pos::before {
  content: ''; position: absolute; inset-block: 5px; inset-inline-start: 0;
  width: 4px; border-radius: 4px; background: var(--zone); transition: width .18s ease;
}
.standings--full tbody tr[data-zone]:hover td.pos::before { width: 6px; }
.pos-badge {
  display: inline-grid; place-items: center; min-width: 26px; height: 26px; padding: 0 4px;
  border-radius: 8px; font-weight: 800;
}
.standings--full tr[data-zone] .pos-badge { background: var(--surface-2); background: color-mix(in srgb, var(--zone) 22%, transparent); }
.standings--full td.pts { font-weight: 800; font-size: .95rem; color: var(--text); background: color-mix(in srgb, var(--brand) 7%, transparent); }
.standings--full td.diff.is-pos { color: var(--brand-strong); font-weight: 700; }
[data-theme="dark"] .standings--full td.diff.is-pos { color: var(--brand); }
.standings--full td.diff.is-neg { color: var(--live); font-weight: 700; }
@media (max-width: 640px) { .standings--full .col-optional { display: none; } }

/* Zone legend under the table */
.standings-legend {
  display: flex; flex-wrap: wrap; align-items: center; gap: 8px;
  padding: 12px 16px 14px; border-top: 1px solid var(--border); background: var(--card-head); font-size: .8rem;
}
.standings-legend__title { color: var(--text-muted); font-weight: 800; font-size: .78rem; margin-inline-end: 4px; }
.standings-legend span {
  display: inline-flex; align-items: center; gap: 7px; padding: 5px 12px; border-radius: 999px;
  color: var(--text); font-weight: 700;
  background: var(--surface-2); border: 1px solid var(--border);
  background: color-mix(in srgb, var(--zone) 10%, var(--surface));
  border-color: color-mix(in srgb, var(--zone) 40%, transparent);
}
.standings-legend i {
  width: 10px; height: 10px; border-radius: 50%; display: inline-block; flex-shrink: 0;
  background: var(--zone); box-shadow: 0 0 0 3px color-mix(in srgb, var(--zone) 25%, transparent);
}

.standings-retry {
  margin-top: 8px; min-height: 44px; padding: 8px 18px; border: 0; border-radius: 999px;
  background: var(--brand); color: var(--brand-ink); font: inherit; font-weight: 800; cursor: pointer;
  box-shadow: 0 6px 18px rgba(50, 205, 50, .3);
}

/* ==========================================================================
   Predictions page (/p/predictions.html)
   ========================================================================== */
.predictions-page[hidden], .pred-filter[hidden] { display: none; }
.predictions-page { display: grid; gap: 22px; }

/* Hero + scoring rules */
.pred-hero {
  position: relative; overflow: hidden; display: grid; gap: 10px; justify-items: start;
  padding: 26px 24px; border-radius: calc(var(--radius) + 6px);
  background: radial-gradient(120% 140% at 100% 0%, rgba(50, 205, 50, .20) 0%, transparent 55%), var(--surface);
  border: 1px solid var(--border); box-shadow: var(--shadow);
}
.pred-hero::after {
  content: ''; position: absolute; inset-inline-end: -70px; bottom: -90px; width: 260px; height: 260px;
  border-radius: 50%; background: radial-gradient(circle, rgba(50, 205, 50, .16), transparent 70%); pointer-events: none;
}
.pred-hero > * { position: relative; z-index: 1; }
.pred-hero__eyebrow {
  display: inline-flex; align-items: center; gap: 6px; padding: 5px 12px; border-radius: 999px;
  background: var(--brand-soft); color: var(--brand-strong); font-size: .8rem; font-weight: 800;
}
[data-theme="dark"] .pred-hero__eyebrow { color: var(--brand); }
.pred-hero__eyebrow::before { content: ''; width: 7px; height: 7px; border-radius: 50%; background: currentColor; animation: pxl-chip-dot 1.8s ease-in-out infinite; }
.pred-hero__title { margin: 0; font-size: clamp(1.5rem, 3.4vw, 2.1rem); font-weight: 800; line-height: 1.25; }
.pred-hero__sub { margin: 0; color: var(--text-muted); max-width: 62ch; }
.pred-rules { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 10px; width: 100%; margin-top: 8px; }
.pred-rule {
  display: grid; gap: 2px; justify-items: center; text-align: center; padding: 14px 8px;
  border-radius: var(--radius); background: var(--surface-2); border: 1px solid var(--border); border-top: 3px solid var(--rule);
}
.pred-rule b { font-size: 1.8rem; font-weight: 800; line-height: 1.1; color: var(--rule); }
.pred-rule span { font-size: .82rem; font-weight: 700; color: var(--text-muted); }
.pred-rule--exact { --rule: var(--brand-strong); background: var(--brand-soft); box-shadow: 0 8px 22px rgba(50, 205, 50, .16); }
[data-theme="dark"] .pred-rule--exact { --rule: var(--brand); }
.pred-rule--winner { --rule: #e59e0b; }
.pred-rule--miss { --rule: var(--live); }
.pred-rule--miss b { opacity: .8; }

/* Two-column layout: matches (start / right) + auth & leaderboard (end / left) */
.pred-layout { display: grid; gap: 22px; align-items: start; }
/* The site sidebar is always shown, so the page's own 2 columns need a wide screen;
   below that the account card + leaderboard sit above the matches. */
@media (min-width: 1600px) { .pred-layout { grid-template-columns: minmax(0, 1fr) 340px; } }
@media (max-width: 1599.98px) { .pred-side { order: -1; } }
@media (min-width: 680px) and (max-width: 1599.98px) { .pred-side { grid-template-columns: repeat(2, minmax(0, 1fr)); align-items: start; } }
.pred-main { display: grid; gap: 12px; min-width: 0; }
.pred-main__head { display: flex; flex-wrap: wrap; align-items: center; gap: 6px 12px; }
.pred-main__head .section-title { margin: 0; }
.pred-count { padding: 3px 10px; border-radius: 999px; background: var(--brand-soft); font-size: .76rem; font-weight: 800; }
.pred-count:empty { display: none; }
.pred-note { margin: 0; margin-inline-start: auto; display: inline-flex; align-items: center; gap: 8px; color: var(--text-muted); font-size: .84rem; font-weight: 700; }
.pred-note::before { content: ''; width: 8px; height: 8px; border-radius: 50%; background: var(--live); box-shadow: 0 0 0 4px var(--live-soft); }
.pred-filter { padding: 8px; scroll-padding-inline: 8px; }
.pred-filter .league-chip { min-height: 40px; padding: 6px 14px; font-size: .84rem; }

/* Match cards */
.pred-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(min(100%, 300px), 1fr)); gap: 14px; }
.pred-card, .pred-sk {
  display: grid; gap: 14px; padding: 16px; border-radius: var(--radius);
  background: var(--surface); border: 1px solid var(--border); box-shadow: var(--shadow);
}
.pred-card {
  transition: border-color .2s, box-shadow .2s, transform .2s;
  animation: px-fade-in .35s ease both; animation-delay: calc(var(--i, 0) * 40ms);
}
.pred-card:hover { transform: translateY(-2px); box-shadow: var(--shadow-hover); border-color: var(--brand); }
.pred-card.has-pick { border-color: rgba(50, 205, 50, .45); }
.pred-card.is-locked { background: var(--surface-2); }
.pred-card.is-locked:hover { transform: none; border-color: var(--border); }
.pred-card.is-flash { animation: pred-flash .9s ease; }
@keyframes pred-flash { 0% { box-shadow: 0 0 0 0 rgba(50, 205, 50, .55); } 100% { box-shadow: 0 0 0 16px rgba(50, 205, 50, 0); } }
.pred-card__meta { display: flex; align-items: center; justify-content: space-between; gap: 8px; font-size: .78rem; color: var(--text-muted); font-weight: 700; }
.pred-card__league { display: inline-flex; align-items: center; gap: 6px; min-width: 0; color: var(--text); }
.pred-card__league span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.pred-card__league img { width: 18px; height: 18px; object-fit: contain; flex-shrink: 0; }
.pred-card__meta time { white-space: nowrap; }
.pred-card__teams { display: grid; grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr); align-items: center; gap: 10px; text-align: center; }
.pred-team { display: grid; justify-items: center; gap: 8px; min-width: 0; }
.pred-team img, .pred-team__ph { width: 48px; height: 48px; object-fit: contain; }
.pred-team__ph { display: grid; place-items: center; border-radius: 50%; background: var(--surface-2); color: var(--text-muted); font-weight: 800; }
.pred-team > span:last-child {
  font-weight: 800; font-size: .92rem; line-height: 1.3; overflow: hidden;
  display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical;
}
.pred-vs { padding: 4px 10px; border-radius: 999px; background: var(--surface-2); color: var(--text-muted); font-size: .75rem; font-weight: 800; }
.pred-card.is-locked .pred-vs { background: var(--surface); }
.pred-score { display: flex; align-items: center; justify-content: center; gap: 10px; }
.pred-score__sep { font-weight: 800; color: var(--text-muted); }
.pred-stepper { display: inline-flex; align-items: center; border: 1px solid var(--border); border-radius: 12px; background: var(--surface-2); overflow: hidden; }
.pred-stepper button {
  width: 38px; height: 44px; border: 0; background: transparent; color: var(--text);
  font: inherit; font-size: 1.2rem; font-weight: 800; cursor: pointer; transition: background-color .15s, color .15s;
}
.pred-stepper button:hover:not(:disabled) { background: var(--brand-soft); color: var(--brand-strong); }
.pred-stepper button:disabled { opacity: .35; cursor: not-allowed; }
.pred-stepper button:focus-visible { outline: 2px solid var(--brand); outline-offset: -2px; }
.pred-stepper input {
  width: 46px; height: 44px; border: 0; border-inline: 1px solid var(--border); border-radius: 0;
  background: var(--surface); color: var(--text); text-align: center; font: inherit; font-size: 1.15rem; font-weight: 800;
  -moz-appearance: textfield; appearance: textfield;
}
.pred-stepper input::-webkit-outer-spin-button, .pred-stepper input::-webkit-inner-spin-button { -webkit-appearance: none; margin: 0; }
.pred-stepper input:focus-visible { outline: 2px solid var(--brand); outline-offset: -2px; }
.pred-stepper input:disabled { color: var(--text-muted); }
.pred-save, .pred-submit {
  min-height: 44px; border: 0; border-radius: 12px; cursor: pointer;
  background: linear-gradient(135deg, var(--brand), var(--brand-strong)); color: var(--brand-ink);
  font: inherit; font-weight: 800; box-shadow: 0 6px 18px rgba(50, 205, 50, .28);
  transition: transform .15s, box-shadow .2s, filter .2s;
}
.pred-save:hover:not(:disabled), .pred-submit:hover:not(:disabled) { transform: translateY(-1px); filter: brightness(1.05); }
.pred-save:disabled, .pred-submit:disabled { background: var(--surface-2); color: var(--text-muted); box-shadow: none; cursor: not-allowed; }
.pred-card.is-locked .pred-save:disabled { background: var(--surface); }
.pred-save.is-busy { cursor: progress; }
.pred-status { margin: 0; min-height: 1.3em; text-align: center; font-size: .8rem; font-weight: 700; color: var(--text-muted); }
.pred-status--saved, .pred-status--exact { color: var(--brand-strong); }
[data-theme="dark"] .pred-status--saved, [data-theme="dark"] .pred-status--exact { color: var(--brand); }
.pred-status--winner { color: #d97706; }
[data-theme="dark"] .pred-status--winner { color: #fbbf24; }
.pred-status--miss, .pred-status--error { color: var(--live); }
.pred-status--dirty { color: #d97706; }
.pred-empty {
  grid-column: 1 / -1; display: grid; justify-items: center; gap: 10px; padding: 44px 16px;
  text-align: center; color: var(--text-muted); font-weight: 700;
  background: var(--surface); border: 1px dashed var(--border); border-radius: var(--radius);
}
.pred-sk { --sk-base: var(--border); --sk-shine: rgba(255, 255, 255, .75); }
[data-theme="dark"] .pred-sk { --sk-shine: rgba(62, 230, 62, .10); }
.pred-sk__teams { display: flex; align-items: center; justify-content: space-around; }
.sk--crest { width: 48px; height: 48px; border-radius: 50%; }
.sk--btn { height: 44px; border-radius: 12px; }

/* Sidebar: auth / profile + leaderboard */
.pred-side { display: grid; gap: 18px; align-content: start; min-width: 0; }
.pred-box { background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius); box-shadow: var(--shadow); padding: 16px; }
.pred-tabs { display: grid; grid-template-columns: 1fr 1fr; gap: 4px; padding: 4px; margin-bottom: 14px; border-radius: 12px; background: var(--surface-2); }
.pred-tab { min-height: 40px; border: 0; border-radius: 9px; background: transparent; color: var(--text-muted); font: inherit; font-weight: 800; cursor: pointer; transition: background-color .2s, color .2s; }
.pred-tab.is-active { background: var(--surface); color: var(--text); box-shadow: 0 1px 4px rgba(0, 0, 0, .12); }
.pred-tab:focus-visible { outline: 2px solid var(--brand); outline-offset: 1px; }
.pred-form { display: grid; gap: 12px; }
.pred-form label { display: grid; gap: 6px; font-size: .82rem; font-weight: 800; color: var(--text-muted); }
.pred-form label small { font-weight: 600; }
.pred-form input, .pred-form select {
  min-height: 44px; padding: 8px 12px; border-radius: 10px; border: 1px solid var(--border);
  background: var(--surface-2); color: var(--text); font: inherit; font-size: .95rem;
}
.pred-form input:focus, .pred-form select:focus { outline: none; border-color: var(--brand); box-shadow: 0 0 0 3px var(--brand-soft); }
.pred-form__error { margin: 0; color: var(--live); font-size: .82rem; font-weight: 700; }
.pred-form__error:empty { display: none; }
.pred-form__note { margin: 0; text-align: center; font-size: .75rem; color: var(--text-muted); }
.pred-profile { display: grid; gap: 14px; }
.pred-profile__head { display: flex; align-items: center; gap: 12px; }
.pred-profile__head > div { display: grid; gap: 2px; min-width: 0; }
.pred-profile__head b { font-size: 1.05rem; }
.pred-profile__head small { color: var(--text-muted); font-size: .78rem; }
.pred-avatar {
  width: 48px; height: 48px; flex-shrink: 0; display: grid; place-items: center; border-radius: 50%;
  background: linear-gradient(135deg, var(--brand), var(--brand-strong)); color: var(--brand-ink);
  font-weight: 800; font-size: 1.2rem; box-shadow: 0 0 0 3px var(--brand-soft);
}
.pred-stats { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 8px; }
.pred-stats > div { display: grid; gap: 2px; padding: 10px; border-radius: 12px; background: var(--surface-2); text-align: center; }
.pred-stats b { font-size: 1.3rem; font-weight: 800; }
.pred-stats span { font-size: .75rem; color: var(--text-muted); font-weight: 700; }
.pred-stats .is-brand { background: var(--brand-soft); }
.pred-stats .is-brand b { color: var(--brand-strong); }
[data-theme="dark"] .pred-stats .is-brand b { color: var(--brand); }
.pred-profile__foot { display: flex; align-items: center; justify-content: space-between; gap: 8px; font-size: .8rem; color: var(--text-muted); font-weight: 700; }
.pred-logout {
  min-height: 38px; padding: 6px 14px; border-radius: 999px; border: 1px solid var(--border);
  background: transparent; color: var(--text); font: inherit; font-weight: 700; cursor: pointer; transition: border-color .2s, color .2s;
}
.pred-logout:hover { border-color: var(--live); color: var(--live); }
.pred-board__title { margin: 0 0 4px; display: flex; align-items: center; gap: 8px; font-size: 1.05rem; font-weight: 800; }
.pred-board__title::before { content: ''; width: 4px; height: 18px; border-radius: 3px; background: var(--brand); }
.pred-board__sub { margin: 0 0 14px; color: var(--text-muted); font-size: .8rem; }
.pred-board__list { list-style: none; margin: 0; padding: 6px 0 0; display: grid; gap: 8px; }
.pred-board__empty { margin: 0; padding: 20px 8px; text-align: center; color: var(--text-muted); font-size: .85rem; font-weight: 700; }
.pred-row {
  width: 100%; display: grid; grid-template-columns: 36px minmax(0, 1fr) auto; align-items: center; gap: 10px;
  padding: 10px 12px; border-radius: 12px; border: 1px solid var(--border); background: var(--surface-2);
  color: var(--text); font: inherit; text-align: start; cursor: pointer;
  transition: transform .15s, border-color .2s, box-shadow .2s;
}
.pred-row:hover { transform: translateY(-1px); border-color: var(--brand); box-shadow: 0 6px 16px rgba(0, 0, 0, .10); }
.pred-row:focus-visible { outline: 2px solid var(--brand); outline-offset: 2px; }
.pred-row__rank { position: relative; display: grid; place-items: center; width: 34px; height: 34px; border-radius: 10px; background: var(--surface); font-weight: 800; }
.pred-crown { position: absolute; top: -15px; font-size: .95rem; line-height: 1; filter: drop-shadow(0 2px 3px rgba(0, 0, 0, .25)); }
.pred-row__who { display: grid; gap: 1px; min-width: 0; }
.pred-row__who b, .pred-row__who small { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.pred-row__who b { font-size: .92rem; }
.pred-row__who small { color: var(--text-muted); font-size: .74rem; }
.pred-row__who em { margin-inline-start: 6px; padding: 1px 7px; border-radius: 999px; background: var(--brand); color: var(--brand-ink); font-size: .68rem; font-style: normal; vertical-align: middle; }
.pred-row__pts {
  display: grid; justify-items: center; padding: 6px 10px; border-radius: 10px;
  background: var(--brand-soft); font-weight: 800; font-size: 1rem; line-height: 1.15; white-space: nowrap;
}
.pred-row__pts small { font-size: .68rem; color: var(--text-muted); font-weight: 700; }
.pred-row.is-gold {
  background: linear-gradient(135deg, rgba(250, 204, 21, .30), rgba(245, 158, 11, .10)), var(--surface-2);
  border-color: rgba(245, 158, 11, .6); box-shadow: 0 8px 22px rgba(245, 158, 11, .18);
}
.pred-row.is-gold .pred-row__rank { background: linear-gradient(135deg, #fde047, #f59e0b); color: #3b2500; }
.pred-row.is-gold .pred-row__pts { background: rgba(245, 158, 11, .22); }
.pred-row.is-silver { background: linear-gradient(135deg, rgba(203, 213, 225, .35), transparent), var(--surface-2); border-color: rgba(148, 163, 184, .6); }
.pred-row.is-silver .pred-row__rank { background: linear-gradient(135deg, #f1f5f9, #94a3b8); color: #1e293b; }
.pred-row.is-bronze { background: linear-gradient(135deg, rgba(205, 127, 50, .25), transparent), var(--surface-2); border-color: rgba(205, 127, 50, .55); }
.pred-row.is-bronze .pred-row__rank { background: linear-gradient(135deg, #f0b27a, #cd7f32); color: #3a1d05; }
.pred-row.is-me { box-shadow: 0 0 0 2px var(--brand); }

/* User predictions dialog */
.pred-dialog {
  width: min(560px, calc(100vw - 32px)); max-height: min(82vh, 720px); padding: 0;
  border: 1px solid var(--border); border-radius: calc(var(--radius) + 4px);
  background: var(--surface); color: var(--text); box-shadow: 0 30px 80px rgba(0, 0, 0, .35); overflow: hidden;
}
.pred-dialog[open] { display: flex; flex-direction: column; animation: pred-pop .25s ease; }
.pred-dialog::backdrop { background: rgba(5, 8, 12, .6); -webkit-backdrop-filter: blur(3px); backdrop-filter: blur(3px); }
@keyframes pred-pop { from { opacity: 0; transform: translateY(12px) scale(.98); } to { opacity: 1; transform: none; } }
.pred-dialog__head { display: flex; align-items: center; gap: 12px; padding: 16px; border-bottom: 1px solid var(--border); background: var(--surface-2); }
.pred-dialog__head > div { display: grid; gap: 2px; min-width: 0; flex: 1; }
.pred-dialog__head small { color: var(--text-muted); font-size: .78rem; }
.pred-dialog__close {
  width: 40px; height: 40px; flex-shrink: 0; border-radius: 50%; border: 1px solid var(--border);
  background: var(--surface); color: var(--text); font: inherit; font-size: 1.3rem; line-height: 1; cursor: pointer;
}
.pred-dialog__close:hover { border-color: var(--brand); }
.pred-dialog__body { overflow: auto; padding: 14px 16px 18px; }
.pred-hist { list-style: none; margin: 0; padding: 0; display: grid; gap: 8px; }
.pred-hist li {
  --hist: var(--border);
  display: grid; grid-template-columns: minmax(0, 1fr) auto; align-items: center; gap: 10px;
  padding: 10px 12px; border-radius: 12px; background: var(--surface-2); border-inline-start: 4px solid var(--hist);
}
.pred-hist li.is-exact { --hist: var(--brand); }
.pred-hist li.is-winner { --hist: #f59e0b; }
.pred-hist li.is-miss { --hist: var(--live); }
.pred-hist__match { display: grid; gap: 2px; min-width: 0; }
.pred-hist__match b { font-size: .9rem; }
.pred-hist__match b span { color: var(--text-muted); font-weight: 700; font-size: .78rem; }
.pred-hist__match small { color: var(--text-muted); font-size: .76rem; }
.pred-hist__pts { min-width: 48px; padding: 6px 10px; border-radius: 10px; background: var(--surface); text-align: center; font-weight: 800; }
.pred-hist li.is-exact .pred-hist__pts { background: var(--brand-soft); }

@media (max-width: 600px) {
  .pred-hero { padding: 20px 16px; }
  .pred-rules { gap: 8px; }
  .pred-rule { padding: 12px 4px; }
  .pred-rule b { font-size: 1.45rem; }
  .pred-rule span { font-size: .72rem; }
  .pred-note { margin-inline-start: 0; }
  .pred-team img, .pred-team__ph { width: 42px; height: 42px; }
}

/* ==========================================================================
   Layout: home fixtures now live inside .content-main (sidebar beside them)
   ========================================================================== */
.content-main > .fixtures { padding-block: 0 8px; }
.content-main { min-width: 0; }
.matches-page[hidden], .app-page[hidden], .mc-leagues[hidden] { display: none; }

/* App card: title + text link to /p/app.html, store badges stay direct links */
.app-card__link { display: block; color: inherit; text-decoration: none; border-radius: 10px; margin-bottom: 16px; }
.app-card__link .app-card__text { margin-bottom: 8px; }
.app-card__more { display: inline-flex; align-items: center; gap: 6px; color: #32CD32; font-size: .82rem; font-weight: 800; transition: gap .2s; }
.app-card__link:hover .app-card__title { color: #b8f5b8; }
.app-card__link:hover .app-card__more { gap: 10px; }
.app-card__link:focus-visible { outline: 2px solid #32CD32; outline-offset: 4px; }

/* Match page: live stream block (match_info.stream, merged by the Worker) */
.match-stream { display: grid; gap: 10px; animation: px-fade-in .35s ease both; }
.match-stream[hidden] { display: none; }
.match-stream__head { display: flex; align-items: center; justify-content: space-between; gap: 10px; }
.match-stream__title { margin: 0; display: flex; align-items: center; gap: 8px; font-size: 1.05rem; font-weight: 800; }
.match-stream__title::before { content: ''; width: 4px; height: 18px; border-radius: 3px; background: var(--live); }

/* ==========================================================================
   Matches center (/p/matches.html)
   ========================================================================== */
.matches-page { display: grid; gap: 16px; }
.mc-head { margin-bottom: 0; }
.mc-toolbar {
  display: grid; gap: 12px; padding: 14px; border-radius: calc(var(--radius) + 4px);
  background: var(--surface); border: 1px solid var(--border); box-shadow: var(--shadow);
}
.mc-days { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; }
.mc-day, .mc-picker {
  min-height: 44px; padding: 8px 18px; border-radius: 12px; border: 1px solid var(--border);
  background: var(--surface-2); color: var(--text-muted); font: inherit; font-weight: 800; cursor: pointer;
  transition: background-color .2s, color .2s, border-color .2s, box-shadow .2s;
}
.mc-day:hover, .mc-picker:hover { color: var(--text); border-color: var(--brand); }
.mc-day.is-active, .mc-picker.is-active {
  background: linear-gradient(135deg, var(--brand), var(--brand-strong)); color: var(--brand-ink);
  border-color: transparent; box-shadow: 0 0 0 3px var(--brand-soft), 0 6px 18px rgba(50, 205, 50, .3);
}
.mc-day:focus-visible { outline: 2px solid var(--brand); outline-offset: 2px; }
.mc-picker { display: inline-flex; align-items: center; gap: 8px; padding-block: 0; margin-inline-start: auto; }
.mc-picker svg { width: 18px; height: 18px; flex-shrink: 0; }
.mc-picker input {
  min-height: 42px; border: 0; background: transparent; color: inherit; font: inherit; font-weight: 800;
  color-scheme: light; cursor: pointer;
}
[data-theme="dark"] .mc-picker input { color-scheme: dark; }
.mc-picker.is-active input { color-scheme: light; }
.mc-picker input:focus { outline: none; }
.mc-picker:focus-within { box-shadow: 0 0 0 3px var(--brand-soft); border-color: var(--brand); }
.mc-status { display: flex; gap: 8px; overflow-x: auto; scrollbar-width: none; }
.mc-status::-webkit-scrollbar { display: none; }
.mc-pill {
  flex: 0 0 auto; display: inline-flex; align-items: center; gap: 8px; min-height: 40px; padding: 6px 14px;
  border-radius: 999px; border: 1px solid var(--border); background: transparent; color: var(--text-muted);
  font: inherit; font-size: .88rem; font-weight: 800; cursor: pointer; transition: background-color .2s, color .2s, border-color .2s;
}
.mc-pill:hover { color: var(--text); border-color: var(--brand); }
.mc-pill.is-active { background: var(--text); color: var(--surface); border-color: var(--text); }
.mc-pill--live::before { content: ''; width: 8px; height: 8px; border-radius: 50%; background: var(--live); animation: pxl-pulse 1.4s ease-in-out infinite; }
.mc-pill.mc-pill--live.is-active { background: var(--live); border-color: var(--live); color: #fff; }
.mc-pill.mc-pill--live.is-active::before { background: #fff; }
.mc-count { min-width: 22px; padding: 1px 7px; border-radius: 999px; background: var(--surface-2); color: var(--text); font-size: .75rem; text-align: center; }
.mc-pill.is-active .mc-count { background: rgba(255, 255, 255, .22); color: inherit; }
.mc-search {
  display: flex; align-items: center; gap: 10px; min-height: 46px; padding: 0 14px; border-radius: 12px;
  border: 1px solid var(--border); background: var(--surface-2); color: var(--text-muted); transition: border-color .2s, box-shadow .2s;
}
.mc-search:focus-within { border-color: var(--brand); box-shadow: 0 0 0 3px var(--brand-soft); }
.mc-search svg { width: 18px; height: 18px; flex-shrink: 0; }
.mc-search input { flex: 1; min-width: 0; min-height: 44px; border: 0; background: transparent; color: var(--text); font: inherit; font-size: .95rem; }
.mc-search input:focus { outline: none; }
.mc-leagues { padding: 8px; scroll-padding-inline: 8px; box-shadow: none; background: var(--surface-2); }
.mc-leagues .league-chip { min-height: 40px; padding: 6px 14px; font-size: .84rem; background: var(--surface); }
.mc-leagues .league-chip.is-active { background: linear-gradient(135deg, var(--brand) 0%, var(--brand-strong) 100%); }
.mc-leagues .league-chip[data-empty] { opacity: .5; }
.mc-chip-n { padding: 0 7px; border-radius: 999px; background: var(--surface-2); font-size: .72rem; }
.league-chip.is-active .mc-chip-n { background: rgba(4, 18, 10, .15); }
.mc-list { min-height: 260px; }
.mc-group .league-group__title > span:not(.league-group__count):not(.mc-live-dot) { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.mc-group { animation: px-fade-in .3s ease both; }
.mc-live-dot {
  display: inline-flex; align-items: center; gap: 5px; padding: 2px 9px; border-radius: 999px;
  background: var(--live-soft); color: var(--live); font-size: .72rem; font-weight: 800;
}
.mc-live-dot::before { content: ''; width: 6px; height: 6px; border-radius: 50%; background: currentColor; animation: pxl-pulse 1.4s ease-in-out infinite; }
.mc-empty { border: 1px dashed var(--border); border-radius: var(--radius); background: var(--surface); }
.mc-sk-group { display: grid; gap: 12px; --sk-base: var(--border); --sk-shine: rgba(255, 255, 255, .75); }
[data-theme="dark"] .mc-sk-group { --sk-shine: rgba(62, 230, 62, .10); }
.mc-sk { display: grid; gap: 14px; justify-items: center; padding: 16px; border-radius: var(--radius); background: var(--surface); border: 1px solid var(--border); }
.mc-sk__body { display: flex; align-items: center; justify-content: space-around; width: 100%; }
@media (max-width: 600px) {
  .mc-toolbar { padding: 12px; }
  .mc-day { flex: 1; padding-inline: 10px; }
  .mc-picker { flex: 1 1 100%; margin-inline-start: 0; justify-content: center; }
}

/* ==========================================================================
   App showcase (/p/app.html)
   ========================================================================== */
.app-page { display: grid; gap: 26px; }
.ap-hero {
  position: relative; overflow: hidden; display: grid; gap: 24px; align-items: center;
  padding: 30px 26px; border-radius: calc(var(--radius) + 8px); color: #f1f5f9;
  background: radial-gradient(90% 120% at 100% 0%, rgba(50, 205, 50, .28) 0%, rgba(50, 205, 50, 0) 55%),
    radial-gradient(70% 90% at 0% 100%, rgba(50, 205, 50, .14) 0%, rgba(50, 205, 50, 0) 60%),
    linear-gradient(160deg, #0b1220 0%, #0f172a 45%, #1e293b 100%);
  border: 1px solid #334155; box-shadow: 0 18px 50px rgba(2, 6, 23, .35);
}
@media (min-width: 760px) { .ap-hero { grid-template-columns: minmax(0, 1fr) 230px; } }
.ap-hero__text { display: grid; gap: 14px; justify-items: start; }
.ap-badge {
  display: inline-flex; align-items: center; gap: 8px; padding: 6px 14px; border-radius: 999px;
  background: rgba(50, 205, 50, .14); border: 1px solid rgba(50, 205, 50, .4); color: #b8f5b8; font-size: .82rem; font-weight: 800;
}
.ap-badge::before { content: ''; width: 7px; height: 7px; border-radius: 50%; background: #32CD32; box-shadow: 0 0 10px #32CD32; }
.ap-title { margin: 0; font-size: clamp(1.7rem, 4.2vw, 2.6rem); line-height: 1.25; font-weight: 800; color: #fff; }
.ap-title span { background: linear-gradient(90deg, #7ee87e, #32CD32); -webkit-background-clip: text; background-clip: text; color: transparent; }
.ap-sub { margin: 0; color: #cbd5e1; font-size: 1rem; line-height: 1.8; max-width: 60ch; }
.ap-stores { display: flex; flex-wrap: wrap; gap: 10px; }
.ap-stores .store-badge { min-width: 190px; }
/* Decorative phone */
.ap-phone {
  justify-self: center; width: 210px; aspect-ratio: 9 / 18; padding: 10px; border-radius: 34px;
  background: linear-gradient(160deg, #1e293b, #020617); border: 1px solid #475569;
  box-shadow: 0 30px 60px rgba(0, 0, 0, .45), 0 0 0 6px rgba(50, 205, 50, .08), 0 0 60px rgba(50, 205, 50, .25);
  transform: rotate(-4deg); animation: ap-float 6s ease-in-out infinite;
}
@keyframes ap-float { 0%, 100% { transform: rotate(-4deg) translateY(0); } 50% { transform: rotate(-4deg) translateY(-10px); } }
.ap-phone__screen { display: grid; align-content: start; gap: 10px; height: 100%; padding: 14px 10px; border-radius: 26px; background: #0b1220; overflow: hidden; }
.ap-phone__bar { display: flex; align-items: center; justify-content: space-between; color: #fff; font-size: .78rem; }
.ap-phone__bar i { width: 26px; height: 26px; border-radius: 50%; background: linear-gradient(135deg, #7ee87e, #22a822); }
.ap-mock { border-radius: 14px; background: #111a2e; border: 1px solid #1f2a44; padding: 10px; }
.ap-mock--match { display: flex; align-items: center; justify-content: space-between; }
.ap-mock__crest { width: 30px; height: 30px; border-radius: 50%; background: linear-gradient(135deg, #e2e8f0, #64748b); }
.ap-mock__crest--b { background: linear-gradient(135deg, #fca5a5, #b91c1c); }
.ap-mock__score { color: #fff; font-weight: 800; font-size: 1.05rem; direction: ltr; }
.ap-mock--points { display: flex; align-items: center; justify-content: space-between; background: rgba(50, 205, 50, .14); border-color: rgba(50, 205, 50, .4); color: #b8f5b8; font-size: .72rem; font-weight: 800; }
.ap-mock--points b { color: #32CD32; font-size: .85rem; }
.ap-mock--rank { display: grid; gap: 6px; }
.ap-mock__row { display: flex; align-items: center; gap: 8px; }
.ap-mock__row i { width: 20px; height: 20px; display: grid; place-items: center; border-radius: 6px; background: #1f2a44; color: #cbd5e1; font-size: .65rem; font-style: normal; font-weight: 800; }
.ap-mock__row:first-child i { background: linear-gradient(135deg, #fde047, #f59e0b); color: #3b2500; }
.ap-mock__row em { flex: 1; height: 8px; border-radius: 4px; background: #1f2a44; }
.ap-mock__row b { color: #fbbf24; font-size: .8rem; }
/* Notice */
.ap-notice {
  margin: 0; display: flex; align-items: flex-start; gap: 12px; padding: 14px 16px; border-radius: var(--radius);
  background: rgba(245, 158, 11, .10); border: 1px solid rgba(245, 158, 11, .45); color: var(--text); font-size: .92rem; line-height: 1.7;
}
.ap-notice svg { width: 22px; height: 22px; flex-shrink: 0; margin-top: 2px; color: #d97706; }
[data-theme="dark"] .ap-notice svg { color: #fbbf24; }
/* Sections */
.ap-section { display: grid; gap: 16px; }
.ap-section__head { display: grid; gap: 4px; }
.ap-kicker { color: var(--brand-strong); font-size: .82rem; font-weight: 800; }
[data-theme="dark"] .ap-kicker { color: var(--brand); }
.ap-h2 { margin: 0; font-size: clamp(1.25rem, 2.6vw, 1.6rem); font-weight: 800; }
.ap-features { display: grid; grid-template-columns: repeat(auto-fill, minmax(min(100%, 240px), 1fr)); gap: 14px; }
.ap-feature {
  display: grid; align-content: start; gap: 8px; padding: 18px; border-radius: var(--radius);
  background: var(--surface); border: 1px solid var(--border); box-shadow: var(--shadow);
  transition: transform .2s, border-color .2s, box-shadow .2s;
}
.ap-feature:hover { transform: translateY(-3px); border-color: var(--brand); box-shadow: var(--shadow-hover); }
.ap-feature__icon {
  width: 46px; height: 46px; display: grid; place-items: center; border-radius: 14px;
  background: var(--brand-soft); color: var(--brand-strong); transition: transform .25s;
}
[data-theme="dark"] .ap-feature__icon { color: var(--brand); }
.ap-feature:hover .ap-feature__icon { transform: rotate(-8deg) scale(1.06); }
.ap-feature__icon svg { width: 24px; height: 24px; }
.ap-feature h3 { margin: 4px 0 0; font-size: 1.02rem; font-weight: 800; }
.ap-feature p { margin: 0; color: var(--text-muted); font-size: .9rem; line-height: 1.7; }
.ap-steps { list-style: none; margin: 0; padding: 0; display: grid; gap: 14px; counter-reset: none; }
@media (min-width: 760px) { .ap-steps { grid-template-columns: repeat(3, minmax(0, 1fr)); } }
.ap-step {
  position: relative; display: grid; gap: 10px; justify-items: start; padding: 18px; border-radius: var(--radius);
  background: var(--surface); border: 1px solid var(--border); box-shadow: var(--shadow);
}
.ap-step__n {
  width: 42px; height: 42px; display: grid; place-items: center; border-radius: 50%;
  background: linear-gradient(135deg, var(--brand), var(--brand-strong)); color: var(--brand-ink);
  font-size: 1.15rem; font-weight: 800; box-shadow: 0 0 0 4px var(--brand-soft);
}
.ap-step p { margin: 0; font-weight: 700; line-height: 1.7; }
.ap-faq { display: grid; gap: 10px; }
.ap-q { border-radius: var(--radius); background: var(--surface); border: 1px solid var(--border); box-shadow: var(--shadow); overflow: hidden; transition: border-color .2s; }
.ap-q[open] { border-color: var(--brand); }
.ap-q summary {
  display: flex; align-items: center; justify-content: space-between; gap: 12px; min-height: 52px; padding: 12px 16px;
  font-weight: 800; cursor: pointer; list-style: none;
}
.ap-q summary::-webkit-details-marker { display: none; }
.ap-q summary::after {
  content: '+'; flex-shrink: 0; width: 28px; height: 28px; display: grid; place-items: center; border-radius: 50%;
  background: var(--surface-2); color: var(--text-muted); font-size: 1.1rem; transition: transform .25s, background-color .2s, color .2s;
}
.ap-q[open] summary::after { transform: rotate(45deg); background: var(--brand); color: var(--brand-ink); }
.ap-q summary:focus-visible { outline: 2px solid var(--brand); outline-offset: -2px; }
.ap-q p { margin: 0; padding: 0 16px 16px; color: var(--text-muted); line-height: 1.8; animation: px-fade-in .25s ease; }
.ap-cta {
  display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 16px;
  padding: 22px; border-radius: calc(var(--radius) + 6px);
  background: radial-gradient(120% 140% at 100% 0%, rgba(50, 205, 50, .22) 0%, transparent 60%), var(--surface);
  border: 1px solid var(--border); box-shadow: var(--shadow);
}
.ap-cta p { margin: 4px 0 0; color: var(--text-muted); }
@media (max-width: 600px) {
  .ap-hero { padding: 22px 16px; }
  .ap-phone { width: 170px; }
  .ap-stores .store-badge { flex: 1 1 100%; }
}

/* ==========================================================================
   6b. Portal blocks: header social, app card, community banner, news placeholder
   ========================================================================== */
.header-social { display: flex; align-items: center; gap: 6px; }
.icon-btn.is-telegram:hover { color: #229ED9; border-color: #229ED9; box-shadow: 0 0 14px rgba(34, 158, 217, .35); }
.icon-btn.is-whatsapp:hover { color: #25D366; border-color: #25D366; box-shadow: 0 0 14px rgba(37, 211, 102, .35); }
@media (max-width: 420px) { .header-social { display: none; } }   /* footer + banner keep the links on small phones */

/* App download card: always dark with the lime accent */
.app-card {
  position: relative; overflow: hidden;
  padding: 20px 18px;
  border-radius: var(--radius);
  background: radial-gradient(120% 90% at 100% 0%, rgba(50, 205, 50, .22) 0%, rgba(50, 205, 50, 0) 55%), linear-gradient(160deg, #0f172a 0%, #1e293b 100%);
  border: 1px solid #334155;
  box-shadow: 0 10px 30px rgba(2, 6, 23, .35);
  color: #f1f5f9;
  scroll-margin-top: calc(var(--header-h) + 16px);
}
.app-card__title { margin: 0 0 6px; font-size: 1.1rem; font-weight: 800; display: flex; align-items: center; gap: 8px; color: #fff; }
.app-card__title::before { content: ''; width: 4px; height: 20px; border-radius: 3px; background: #32CD32; box-shadow: 0 0 14px rgba(50, 205, 50, .6); }
.app-card__text { margin: 0 0 16px; color: #94a3b8; font-size: .88rem; line-height: 1.6; }
.app-card__badges { display: grid; gap: 10px; }
.store-badge {
  display: flex; align-items: center; gap: 12px;
  padding: 10px 14px; border-radius: 12px;
  background: #0b1220; border: 1px solid #334155; color: #f8fafc;
  transition: border-color .2s, box-shadow .2s, transform .15s;
}
.store-badge:hover { border-color: #32CD32; box-shadow: 0 0 18px rgba(50, 205, 50, .35); transform: translateY(-2px); color: #fff; }
.store-badge svg { width: 26px; height: 26px; flex-shrink: 0; }
.store-badge__text { display: flex; flex-direction: column; line-height: 1.25; }
.store-badge__text small { font-size: .7rem; color: #94a3b8; font-weight: 600; }
.store-badge__text strong { font-size: 1.02rem; font-weight: 800; direction: ltr; text-align: right; }

/* Community banner (home, below the matches) */
.community-banner {
  margin-top: 26px;
  display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 18px;
  padding: 22px 24px;
  border-radius: calc(var(--radius) + 4px);
  background: radial-gradient(90% 140% at 0% 50%, rgba(50, 205, 50, .18) 0%, rgba(50, 205, 50, 0) 60%), linear-gradient(135deg, #0f172a 0%, #1e293b 100%);
  border: 1px solid #334155;
  box-shadow: 0 10px 30px rgba(2, 6, 23, .25);
  color: #f1f5f9;
}
.community-banner__text { display: flex; align-items: center; gap: 14px; min-width: 0; }
.community-banner__icon {
  width: 46px; height: 46px; flex-shrink: 0; border-radius: 14px;
  display: grid; place-items: center; background: rgba(50, 205, 50, .15); color: #32CD32;
}
.community-banner__icon svg { width: 24px; height: 24px; }
.community-banner h2 { margin: 0; font-size: 1.08rem; font-weight: 800; line-height: 1.5; color: #fff; }
.community-banner p { margin: 2px 0 0; color: #94a3b8; font-size: .86rem; }
.community-banner__actions { display: flex; flex-wrap: wrap; gap: 10px; }
.btn-social {
  display: inline-flex; align-items: center; gap: 8px;
  padding: 10px 18px; border-radius: 999px;
  font-weight: 800; font-size: .92rem; color: #fff;
  transition: transform .15s, box-shadow .2s, filter .2s;
}
.btn-social svg { width: 18px; height: 18px; }
.btn-social:hover { transform: translateY(-2px); color: #fff; filter: brightness(1.08); }
.btn-social--telegram { background: #229ED9; box-shadow: 0 6px 18px rgba(34, 158, 217, .35); }
.btn-social--whatsapp { background: #25D366; color: #06240f; box-shadow: 0 6px 18px rgba(37, 211, 102, .35); }
.btn-social--whatsapp:hover { color: #06240f; }
@media (max-width: 600px) {
  .community-banner { padding: 18px; }
  .community-banner__actions { width: 100%; }
  .btn-social { flex: 1 1 0; justify-content: center; }
}

/* Social channels banner directly under the live player (match post arena).
   Theme tokens for the card (light/dark), brand colours on the buttons (.btn-social--*). */
.stream-social {
  display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 12px 16px;
  padding: 14px 16px; border-radius: var(--radius);
  background: var(--surface); border: 1px solid var(--border); box-shadow: var(--shadow);
}
.stream-social__text { display: flex; align-items: center; gap: 12px; min-width: 0; }
.stream-social__icon {
  width: 40px; height: 40px; flex-shrink: 0; display: grid; place-items: center; border-radius: 12px;
  background: var(--brand-soft); color: var(--brand-strong);
}
[data-theme="dark"] .stream-social__icon { color: var(--brand); }
.stream-social__icon svg { width: 22px; height: 22px; }
.stream-social__title { margin: 0; font-size: 1rem; font-weight: 800; line-height: 1.5; color: var(--text); }
.stream-social__sub { margin: 0; font-size: .82rem; color: var(--text-muted); }
.stream-social__actions { display: flex; flex-wrap: wrap; gap: 10px; }
.stream-social .btn-social { min-height: 44px; justify-content: center; }
@media (max-width: 600px) {
  .stream-social { padding: 12px; }
  .stream-social__actions { width: 100%; }
}

/* Latest news placeholder (shown while the blog has no posts) */
.news-placeholder .card { pointer-events: none; }
.news-placeholder .card:hover { transform: none; box-shadow: var(--shadow); border-color: var(--border); }
.skeleton-block {
  display: block; border-radius: 8px;
  background: linear-gradient(90deg, var(--surface-2) 0%, var(--border) 50%, var(--surface-2) 100%);
  background-size: 200% 100%;
  animation: px-shimmer 1.4s ease-in-out infinite;
}
.news-placeholder .card__media .skeleton-block { position: absolute; inset: 0; border-radius: 0; }
.skeleton-line { height: 12px; }
.skeleton-line--title { height: 16px; width: 85%; }
.skeleton-line--short { width: 55%; }
.skeleton-tag { width: 64px; height: 20px; border-radius: 999px; }
@keyframes px-shimmer { from { background-position: 200% 0; } to { background-position: -200% 0; } }
.news-placeholder__note { margin: 14px 0 0; text-align: center; color: var(--text-muted); font-size: .85rem; }

/* ==========================================================================
   7. Footer
   ========================================================================== */
.site-footer { background: var(--surface); border-top: 1px solid var(--border); padding-top: 40px; }
[data-theme="dark"] .site-footer { background: #05070a; }
.footer-grid { display: grid; grid-template-columns: 1fr; gap: 28px; }
@media (min-width: 640px) { .footer-grid { grid-template-columns: repeat(2, 1fr); } }
@media (min-width: 1024px) { .footer-grid { grid-template-columns: 1.4fr 1fr 1fr 1fr; } }
.footer-col h3 { margin: 0 0 12px; font-size: 1rem; font-weight: 800; }
.footer-col p { margin: 0; color: var(--text-muted); font-size: .92rem; }
.footer-links { list-style: none; margin: 0; padding: 0; display: grid; gap: 8px; }
.footer-links a { color: var(--text-muted); font-size: .92rem; }
.footer-links a:hover { color: var(--brand-strong); }
.social { display: flex; flex-wrap: wrap; gap: 10px; }
.social a {
  width: 44px; height: 44px; display: grid; place-items: center; border-radius: 12px;
  border: 1px solid var(--border); background: var(--surface-2);
  transition: border-color .2s, box-shadow .2s, color .2s;
}
.social a:hover { border-color: var(--brand); color: var(--brand-strong); box-shadow: var(--brand-glow); }
.social svg { width: 18px; height: 18px; }
.social a.is-telegram:hover { color: #229ED9; border-color: #229ED9; }
.social a.is-whatsapp:hover { color: #25D366; border-color: #25D366; }
.footer-apps { display: grid; gap: 8px; margin-top: 14px; }
.footer-apps a { display: inline-flex; align-items: center; gap: 8px; color: var(--text-muted); font-size: .9rem; }
.footer-apps a:hover { color: var(--brand-strong); }
.footer-apps svg { width: 18px; height: 18px; }
.footer-bottom {
  margin-top: 32px; padding-block: 18px; border-top: 1px solid var(--border);
  display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 10px;
  color: var(--text-muted); font-size: .85rem;
}

/* ==========================================================================
   8. Cross-device hardening (320px phones -> 4K TVs)
   ========================================================================== */
/* Last-resort guard against a stray wide element causing sideways page scroll.
   'clip' (not 'hidden') creates no scroll container, so the sticky header keeps working. */
body { overflow-x: clip; }

/* Touch devices: comfortable 44px targets for text links too, without changing the desktop look */
@media (pointer: coarse) {
  .footer-links a, .footer-apps a { display: inline-flex; align-items: center; min-height: 44px; }
  .footer-links { gap: 0; }
  .pager a { min-height: 44px; }
  .post-labels a { display: inline-flex; align-items: center; min-height: 44px; }
}

/* Small phones (iPhone SE / low-end Android, 320-360px) */
@media (max-width: 360px) {
  .container { padding-inline: 12px; }
  .match-card__body { gap: 8px; padding: 14px 10px; }
  .match-card__top, .match-card__bottom { padding-inline: 12px; }
  .team__logo { width: 48px; height: 48px; }
  .team__logo img { width: 34px; height: 34px; }
  .team__name { font-size: .86rem; }
  .match-center { min-width: 80px; }
  .match-time { font-size: 1.15rem; padding-inline: 10px; }
  .match-score { font-size: 1.3rem; padding-inline: 10px; gap: 6px; }
  .mh__teams { gap: 8px; padding-inline: 10px; }
  .mh__logo { width: 54px; height: 54px; }
  .mh__logo img { width: 38px; height: 38px; }
  .mh__center { min-width: 80px; }
  .mh__score { font-size: 1.75rem; gap: 8px; }
  .mh__time { font-size: 1.3rem; padding-inline: 10px; }
  .match-panel { padding: 10px; }
  .match-tab { padding-inline: 8px; font-size: .86rem; }
  .pitch { padding-inline: 4px; }
  .pl__name { font-size: .64rem; }
  .pl__rating { inset-inline-end: -8px; }
  .post-full { padding: 16px; }
}

/* Standings on phones: truncate long team names instead of forcing the table wider than the card */
@media (max-width: 420px) {
  .standings--full th, .standings--full td { padding: 9px 5px; }
  .standings--full td:nth-child(2) { min-width: 0; }
  .standings--full .team-cell { max-width: 42vw; }              /* td ignores max-width; the flex cell honours it */
  .standings--full .team-cell span { min-width: 0; }
}

/* Large monitors and Smart TVs: wider container, 3 match columns, rem scale for 10-foot viewing */
@media (min-width: 1600px) {
  :root { --container: 1440px; }
  .match-list { grid-template-columns: repeat(3, minmax(0, 1fr)); }
}
@media (min-width: 1920px) {
  html { font-size: 112.5%; }
  :root { --container: 1600px; --header-h: 72px; }
  :focus-visible { outline-width: 3px; outline-offset: 3px; }   /* D-pad / remote navigation */
}
@media (min-width: 2560px) {
  html { font-size: 125%; }
  :root { --container: 1920px; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation: none !important; transition: none !important; scroll-behavior: auto !important; }
}

/* ==========================================================================
   Static intro text (home + standings) and the no-JavaScript fallback
   ========================================================================== */
.site-intro { margin: 0 0 18px; color: var(--text-muted); font-size: .95rem; line-height: 1.85; }
.site-intro strong { color: var(--text); }
.noscript-box {
  margin: 0 0 18px; padding: 14px 16px; border-radius: var(--radius-sm);
  background: var(--surface); border: 1px solid var(--border); color: var(--text); font-size: .92rem;
}
.noscript-box a { color: var(--brand-strong); font-weight: 700; }

head.b:template-skin:
body#layout { background: #f6f7f9; font-family: Arial, sans-serif; }
body#layout .header-inner, body#layout .main-nav, body#layout .header-actions,
body#layout .fixtures, body#layout .arena-head, body#layout .player-frame { display: none; }
body#layout .arena-grid, body#layout .content-wrap, body#layout .footer-grid { display: flex; gap: 8px; }
body#layout .arena-center, body#layout .content-main, body#layout .footer-grid > * { flex: 1; }
body#layout .ad-slot { display: block; }
body#layout .sidebar { width: 320px; }

b:if.script:
//
(function () {
  var route = window.PXL_ROUTE;
  if (!route) return;
  var section = document.getElementById(route + '-page');   // standings-page / match-page / predictions-page
  var main = document.getElementById('main');
  if (section) section.hidden = false;
  if (main) main.hidden = true;
  var links = document.querySelectorAll('#main-nav a[href$="/p/' + route + '.html"]');
  for (var i = 0; i < links.length; i++) links[i].classList.add('is-active');
})();
//

//
(function () {
  if (window.PXL_ROUTE !== 'news') return;
  var PER_PAGE = 12;
  var grid = document.getElementById('news-grid');
  var pager = document.getElementById('news-pager');
  var status = document.getElementById('news-status');
  if (!grid) return;
  var page = parseInt(new URLSearchParams(location.search).get('page'), 10);
  if (!(page >= 1 && page < 10000)) page = 1;

  function esc(s) {
    return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }
  function cover(url) {
    // Feed thumbnails are 72px squares (/s72-c/ or =s72-c): ask the CDN for a 640x360 crop.
    if (!url) return '';
    return url.replace(/\/s72-c(-[^/]*)?\//, '/w640-h360-p-k-no-nu/').replace(/=s72-c(-[^/]*)?$/, '=w640-h360-p-k-no-nu');
  }
  function excerpt(text) {
    text = String(text || '').replace(/\s+/g, ' ').trim();
    if (text.length <= 170) return text;
    var cut = text.slice(0, 170);
    var sp = cut.lastIndexOf(' ');
    return (sp > 100 ? cut.slice(0, sp) : cut) + '…';
  }
  var dateFmt;
  try { dateFmt = new Intl.DateTimeFormat('ar-EG', { day: 'numeric', month: 'long', year: 'numeric', timeZone: 'Africa/Cairo' }); } catch (e) {}
  function fmtDate(iso) {
    var d = new Date(iso);
    if (isNaN(d)) return '';
    return dateFmt ? dateFmt.format(d) : d.toISOString().slice(0, 10);
  }
  function pageHref(n) { return n > 1 ? '?page=' + n : location.pathname; }

  function card(e) {
    var link = '';
    (e.link || []).forEach(function (l) { if (l.rel === 'alternate') link = l.href; });
    var title = e.title && e.title.$t;
    if (!title || !link) return '';
    var img = cover(e.media$thumbnail && e.media$thumbnail.url);
    var label = e.category && e.category[0] && e.category[0].term;
    var iso = e.published && e.published.$t;
    return '<article class="card">' +
      '<a class="card__media" href="' + esc(link) + '" aria-label="' + esc(title) + '">' +
        (img ? '<img src="' + esc(img) + '" alt="' + esc(title) + '" width="640" height="360" loading="lazy" decoding="async">'
             : '<span class="card__placeholder">PX</span>') +
      '</a>' +
      '<div class="card__body">' +
        (label ? '<a class="card__tag" href="/search/label/' + encodeURIComponent(label) + '">' + esc(label) + '</a>' : '') +
        '<h2 class="card__title"><a href="' + esc(link) + '">' + esc(title) + '</a></h2>' +
        '<p class="card__excerpt">' + esc(excerpt(e.summary && e.summary.$t)) + '</p>' +
        (iso ? '<time class="card__date" datetime="' + esc(iso) + '">' + esc(fmtDate(iso)) + '</time>' : '') +
      '</div></article>';
  }

  function renderPager(pages) {
    if (pages <= 1) { pager.hidden = true; return; }
    var out = [];
    if (page > 1) out.push('<a href="' + pageHref(page - 1) + '" rel="prev">&#8594; الأحدث</a>');
    var last = 0;
    for (var n = 1; n <= pages; n++) {
      if (n !== 1 && n !== pages && Math.abs(n - page) > 1) continue;
      if (last && n - last > 1) out.push('<span class="news-pager__gap" aria-hidden="true">…</span>');
      out.push(n === page ? '<span aria-current="page">' + n + '</span>'
                          : '<a href="' + pageHref(n) + '" aria-label="الصفحة ' + n + '">' + n + '</a>');
      last = n;
    }
    if (page < pages) out.push('<a href="' + pageHref(page + 1) + '" rel="next">الأقدم &#8592;</a>');
    pager.innerHTML = out.join('');
    pager.hidden = false;
  }

  function fail() {
    grid.innerHTML = '<div class="empty-state" style="grid-column:1/-1">تعذّر تحميل الأخبار الآن. <a class="px-retry" href="' + esc(location.href) + '">إعادة المحاولة</a></div>';
    if (status) status.textContent = '';
  }

  var url = '/feeds/posts/summary?alt=json&max-results=' + PER_PAGE + '&start-index=' + ((page - 1) * PER_PAGE + 1);
  fetch(url, { credentials: 'omit' }).then(function (r) {
    if (!r.ok) throw new Error('HTTP ' + r.status);
    return r.json();
  }).then(function (data) {
    var feed = data && data.feed || {};
    var entries = feed.entry || [];
    var total = parseInt(feed.openSearch$totalResults && feed.openSearch$totalResults.$t, 10) || 0;
    var pages = Math.max(1, Math.ceil(total / PER_PAGE));
    if (page > pages && total) { location.replace(pageHref(pages)); return; }
    var html = entries.map(card).join('');
    grid.innerHTML = html || '<div class="empty-state" style="grid-column:1/-1">لا توجد أخبار منشورة بعد.</div>';
    if (status) status.textContent = total ? ('عدد الأخبار المنشورة: ' + total + (pages > 1 ? ' — الصفحة ' + page + ' من ' + pages : '')) : '';
    renderPager(pages);

    // Structured data: this archive page as a CollectionPage listing its articles.
    if (window.pxlSeo) {
      var base = (window.PXL_SITE_URL || location.origin).replace(/\/+$/, '');
      var items = [];
      entries.forEach(function (e) {
        var href = '';
        (e.link || []).forEach(function (l) { if (l.rel === 'alternate') href = l.href; });
        if (href && e.title && e.title.$t) items.push({ '@type': 'ListItem', position: (page - 1) * PER_PAGE + items.length + 1, url: href, name: e.title.$t });
      });
      window.pxlSeo.jsonLd('pxl-ld-news', {
        '@context': 'https://schema.org',
        '@type': 'CollectionPage',
        name: document.title,
        url: base + location.pathname + (page > 1 ? '?page=' + page : ''),
        inLanguage: 'ar',
        isPartOf: { '@type': 'WebSite', '@id': base + '/#website', url: base + '/', name: 'PX League' },
        publisher: { '@type': 'Organization', '@id': base + '/#organization', name: 'PX League', url: base + '/' },
        mainEntity: { '@type': 'ItemList', itemListElement: items }
      });
    }
  }).catch(fail);
})();
//

//
(function () {
  var card = document.getElementById('home-news');
  var slot = document.getElementById('home-news-slot');
  if (card && slot) slot.parentNode.replaceChild(card, slot);
})();
