body.script:
//
(function () {
  var root = document.documentElement;
  var toggle = document.getElementById('theme-toggle');
  function applyTheme(theme) {
    root.setAttribute('data-theme', theme);
    toggle.setAttribute('aria-pressed', theme === 'dark' ? 'true' : 'false');
    var meta = document.querySelector('meta[name="theme-color"]');
    if (meta) meta.setAttribute('content', theme === 'dark' ? '#07090c' : '#32cd32');
  }
  applyTheme(root.getAttribute('data-theme') === 'dark' ? 'dark' : 'light');
  toggle.addEventListener('click', function () {
    var next = root.getAttribute('data-theme') === 'dark' ? 'light' : 'dark';
    applyTheme(next);
    try { localStorage.setItem('pxl-theme', next); } catch (e) {}
  });

  var menuBtn = document.getElementById('menu-toggle');
  var nav = document.getElementById('main-nav');
  function setMenu(open) {
    nav.classList.toggle('is-open', open);
    menuBtn.setAttribute('aria-expanded', open ? 'true' : 'false');
    menuBtn.setAttribute('aria-label', open ? 'إغلاق القائمة' : 'فتح القائمة');
  }
  menuBtn.addEventListener('click', function () { setMenu(!nav.classList.contains('is-open')); });
  nav.addEventListener('click', function (e) { if (e.target.closest('a')) setMenu(false); });
  document.addEventListener('keydown', function (e) { if (e.key === 'Escape') setMenu(false); });
  // Close the mobile menu when the layout switches to desktop. matchMedia fires once per
  // breakpoint crossing; a 'resize' listener fired on every frame of a resize/rotation.
  var desktopMq = window.matchMedia('(min-width: 861px)');
  var onMq = function (e) { if (e.matches) setMenu(false); };
  if (desktopMq.addEventListener) desktopMq.addEventListener('change', onMq); else desktopMq.addListener(onMq);

  var y = document.getElementById('pxl-year');
  if (y) y.textContent = String(new Date().getFullYear());
})();
//

b:if.script:
//
(function () {
  'use strict';
  if (location.pathname !== '/p/standings.html') return;   // client-side route guard

  var WORKER_BASE_URL = window.PXL_WORKER_BASE_URL || '';
  var STANDINGS_PATH = '/api/standings/{id}?include=results';
  var TEAM_LOGO_BASE = 'https://imgs.ysscores.com/teams/128/';

  var board = document.getElementById('standings-board');
  var filter = document.getElementById('league-filter');
  if (!board || !filter) return;
  var chips = Array.prototype.slice.call(filter.querySelectorAll('.league-chip'));

  var ESC = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' };
  function esc(v) { return String(v == null ? '' : v).replace(/[&<>"']/g, function (c) { return ESC[c]; }); }
  function pick() {
    for (var i = 0; i < arguments.length; i++) if (arguments[i] != null && arguments[i] !== '') return arguments[i];
    return '';
  }
  function imgUrl(value) {
    var v = String(value || '').trim();
    if (/^https:\/\//i.test(v)) return v;
    return /^[\w.-]+\.(png|jpe?g|webp|gif|svg)$/i.test(v) ? TEAM_LOGO_BASE + encodeURIComponent(v) : '';
  }
  function safeColor(c) { return /^#[0-9a-f]{3,8}$/i.test(String(c || '')) ? c : ''; }

  // ------------------------------------------------------------------ parsing
  function parseRow(r, i) {
    var zone = r.zone && typeof r.zone === 'object' ? r.zone : {};
    var diff = pick(r.goalDiff, r.diff, r.goal_difference,
      (r.goalsFor != null && r.goalsAgainst != null) ? Number(r.goalsFor) - Number(r.goalsAgainst) : 0);
    return {
      rank: Number(pick(r.rank, r.position, i + 1)) || i + 1,
      name: pick(r.teamName, r.team_name && r.team_name.short_title, r.name),
      logo: imgUrl(pick(r.teamLogo, r.team_name && r.team_name.image, r.logo)),
      played: pick(r.played, r.play, 0),
      won: pick(r.won, r.win, 0),
      drawn: pick(r.drawn, r.draw, 0),
      lost: pick(r.lost, r.lose, 0),
      gf: pick(r.goalsFor, r.for, 0),
      ga: pick(r.goalsAgainst, r.against, 0),
      diff: Number(diff) || 0,
      points: pick(r.points, r.pts, 0),
      zoneColor: safeColor(zone.color),
      zoneLabel: zone.label || ''
    };
  }
  function parseResponse(json) {
    var groups = Array.isArray(json && json.groups) ? json.groups : [];
    return {
      league: (json && json.league) || '',
      logo: imgUrl(json && json.leagueLogo),
      groups: groups.map(function (g) {
        return {
          name: g.name || g.title || '',
          rows: (Array.isArray(g.rows) ? g.rows : []).map(parseRow).sort(function (a, b) { return a.rank - b.rank; })
        };
      }).filter(function (g) { return g.rows.length; })
    };
  }

  // ------------------------------------------------------------------ rendering
  function rowHtml(t, i) {
    var diffText = t.diff > 0 ? '+' + t.diff : String(t.diff);
    var diffCls = t.diff > 0 ? ' is-pos' : (t.diff < 0 ? ' is-neg' : '');
    var style = '--i:' + Math.min(i || 0, 24) + (t.zoneColor ? ';--zone:' + esc(t.zoneColor) : '');
    return `<tr style="${style}"${t.zoneColor ? ` data-zone title="${esc(t.zoneLabel)}"` : ''}>
      <td class="pos"><span class="pos-badge">${esc(t.rank)}</span></td>
      <td><span class="team-cell">${t.logo ? `<img src="${esc(t.logo)}" alt="" loading="lazy" referrerpolicy="no-referrer" onerror="this.remove()">` : ''}<span>${esc(t.name)}</span></span></td>
      <td>${esc(t.played)}</td>
      <td class="col-optional">${esc(t.won)}</td>
      <td class="col-optional">${esc(t.drawn)}</td>
      <td class="col-optional">${esc(t.lost)}</td>
      <td class="col-optional">${esc(t.gf)}</td>
      <td class="col-optional">${esc(t.ga)}</td>
      <td class="diff${diffCls}" dir="ltr">${esc(diffText)}</td>
      <td class="pts">${esc(t.points)}</td>
    </tr>`;
  }
  function legendHtml(rows) {
    var seen = {};
    var items = [];
    rows.forEach(function (t) {
      if (t.zoneColor && t.zoneLabel && !seen[t.zoneLabel]) {
        seen[t.zoneLabel] = true;
        items.push(`<span style="--zone:${esc(t.zoneColor)}"><i></i>${esc(t.zoneLabel)}</span>`);
      }
    });
    return items.length ? `<div class="standings-legend"><b class="standings-legend__title">دليل الألوان:</b>${items.join('')}</div>` : '';
  }
  function render(data) {
    if (!data.groups.length) { message('لا يتوفر جدول الترتيب لهذا الدوري حاليًا.', false); return; }
    var multi = data.groups.length > 1;
    board.innerHTML = data.groups.map(function (g) {
      return `
        <article class="standings-card">
          <div class="standings-card__head">
            ${data.logo ? `<img src="${esc(data.logo)}" alt="" loading="lazy" referrerpolicy="no-referrer" onerror="this.remove()">` : ''}
            <span>${esc(multi && g.name ? data.league + ' – ' + g.name : data.league)}</span>
            <small>${g.rows.length} فريقًا</small>
          </div>
          <div class="standings-scroll">
            <table class="standings standings--full">
              <thead><tr>
                <th>#</th><th>الفريق</th><th>لعب</th>
                <th class="col-optional">فوز</th><th class="col-optional">تعادل</th><th class="col-optional">خسارة</th>
                <th class="col-optional">له</th><th class="col-optional">عليه</th>
                <th>+/-</th><th>نقاط</th>
              </tr></thead>
              <tbody>${g.rows.map(rowHtml).join('')}</tbody>
            </table>
          </div>
          ${legendHtml(g.rows)}
        </article>`;
    }).join('');
    board.classList.add('is-ready');
  }
  var SKELETON_WIDTHS = [62, 48, 70, 55, 66, 44, 58, 72, 50, 64];   // name bar widths (%)
  function skeletonHtml() {
    var rows = SKELETON_WIDTHS.map(function (w, i) {
      return `<div class="sk-row" style="--i:${i}"><span class="sk sk--pos"></span><span class="sk sk--logo"></span>` +
        `<span class="sk sk--name" style="width:${w}%"></span><span class="sk sk--num"></span>` +
        `<span class="sk sk--num sk--opt"></span><span class="sk sk--num"></span></div>`;
    }).join('');
    return `<div class="standings-skeleton" role="status" aria-busy="true">
      <span class="visually-hidden">جاري تحميل الترتيب...</span>
      <div class="sk-head"><span class="sk sk--logo"></span><span class="sk sk--title"></span><span class="sk sk--badge"></span></div>
      ${rows}
    </div>`;
  }
  function loading() {
    board.classList.remove('is-ready');
    board.innerHTML = skeletonHtml();
  }
  function message(text, retryId) {
    board.classList.remove('is-ready');
    board.innerHTML = `<div class="standings-message"><span>${esc(text)}</span>${retryId ? '<button class="standings-retry" type="button">إعادة المحاولة</button>' : ''}</div>`;
    var btn = board.querySelector('.standings-retry');
    if (btn) btn.addEventListener('click', function () { fetchStandings(retryId); });
  }

  // ------------------------------------------------------------------ fetching
  var cache = {};                     // id -> parsed data (instant switching back)
  var requestSeq = 0;

  async function fetchStandings(championshipId) {
    var id = String(championshipId);
    var mySeq = ++requestSeq;           // ignore responses for a league the user already left
    if (cache[id]) { render(cache[id]); return; }
    loading();
    if (!WORKER_BASE_URL || WORKER_BASE_URL.indexOf('<MY_WORKER_URL>') !== -1) {
      console.error('[PX League] Set PXL_WORKER_BASE_URL (top of the theme) to load the standings.');
      return;                            // keep the spinner
    }
    var url = WORKER_BASE_URL + STANDINGS_PATH.replace('{id}', encodeURIComponent(id));
    for (var attempt = 1; attempt <= 3; attempt++) {
      var ctrl = new AbortController();
      var timer = setTimeout(function () { ctrl.abort(); }, 10000);
      try {
        var res = await fetch(url, { headers: { Accept: 'application/json' }, signal: ctrl.signal });
        if (!res.ok) throw new Error('HTTP ' + res.status);
        var data = parseResponse(await res.json());
        cache[id] = data;
        if (mySeq === requestSeq) render(data);
        return;
      } catch (err) {
        if (attempt === 3) {
          console.warn('[PX League] standings:', err);
          if (mySeq === requestSeq) message('تعذّر تحميل الترتيب حاليًا.', id);
        } else {
          await new Promise(function (r) { setTimeout(r, 1000 * attempt); });
        }
      } finally {
        clearTimeout(timer);
      }
    }
  }

  // ------------------------------------------------------------------ league filter
  function selectLeague(chip, updateUrl) {
    chips.forEach(function (c) {
      var on = c === chip;
      c.classList.toggle('is-active', on);
      c.setAttribute('aria-selected', on ? 'true' : 'false');
    });
    centerChip(chip);
    if (updateUrl) {
      try { history.replaceState(null, '', '#league=' + chip.getAttribute('data-id')); } catch (e) {}
    }
    fetchStandings(chip.getAttribute('data-id'));
  }
  // Center the chip by scrolling the filter only. scrollIntoView() could also scroll the page
  // vertically (jump on load / on phones). A rect delta is direction-agnostic, so it works in
  // RTL whatever scrollLeft convention the browser uses.
  function centerChip(chip) {
    var fr = filter.getBoundingClientRect(), cr = chip.getBoundingClientRect();
    var delta = (cr.left + cr.width / 2) - (fr.left + fr.width / 2);
    if (Math.abs(delta) < 2) return;
    var smooth = !(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches);
    if (filter.scrollBy) filter.scrollBy({ left: delta, behavior: smooth ? 'smooth' : 'auto' });
    else filter.scrollLeft += delta;
  }
  filter.addEventListener('click', function (e) {
    var chip = e.target.closest('.league-chip');
    if (chip && !chip.classList.contains('is-active')) selectLeague(chip, true);
  });
  filter.addEventListener('keydown', function (e) {   // arrow keys move between leagues
    var i = chips.indexOf(document.activeElement);
    if (i === -1 || (e.key !== 'ArrowLeft' && e.key !== 'ArrowRight')) return;
    e.preventDefault();
    var step = e.key === 'ArrowLeft' ? 1 : -1;           // RTL: left = next
    var next = chips[(i + step + chips.length) % chips.length];
    next.focus();
    selectLeague(next, true);
  });

  window.fetchStandings = fetchStandings;

  // Initial league: #league=ID in the URL, otherwise the first chip
  var m = /league=(\d+)/.exec(location.hash);
  var initial = (m && chips.filter(function (c) { return c.getAttribute('data-id') === m[1]; })[0]) || chips[0];
  selectLeague(initial, false);
})();
//

//
(function () {
  'use strict';
  if (location.pathname !== '/p/matches.html') return;   // client-side route guard

  // ------------------------------------------------------------------ config
  var WORKER_BASE_URL = window.PXL_WORKER_BASE_URL || '';
  var MATCH_FILTERS = '[]/[]/["8634"]';                  // same feed as the home page
  var TEAM_LOGO_BASE = 'https://imgs.ysscores.com/teams/128/';
  var LEAGUE_LOGO_BASE = 'https://imgs.ysscores.com/championship/64/';
  var TZ = 'Africa/Cairo';
  var REFRESH_LIVE_MS = 30 * 1000;                         // today with a live match
  var REFRESH_IDLE_MS = 2 * 60 * 1000;                     // today, nothing live
  var LIVE_WINDOW_MS = 3.5 * 60 * 60 * 1000;
  // League order: these first (same ids as the standings / predictions pages), then the rest.
  var PRIORITY = ['937599', '943230', '938652', '943009', '941825', '936357', '938769', '937873',
    '20580897', '943487', '943229', '943231', '34872360', '942806', '97887515', '938823', '939779',
    '939531', '941155', '943983', '54771544', '41791876'];

  var root = document.getElementById('matches-page');
  var listEl = document.getElementById('mc-list');
  var dayBar = document.getElementById('mc-days');
  var statusBar = document.getElementById('mc-status');
  var leagueBar = document.getElementById('mc-leagues');
  var searchEl = document.getElementById('mc-search');
  var dateInput = document.getElementById('mc-date');
  var dateLabel = document.getElementById('mc-date-label');
  if (!root || !listEl || !dayBar || !statusBar || !leagueBar) return;

  // ------------------------------------------------------------------ helpers
  var ESC = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' };
  function esc(v) { return String(v == null ? '' : v).replace(/[&<>"']/g, function (c) { return ESC[c]; }); }
  function wait(ms) { return new Promise(function (r) { setTimeout(r, ms); }); }
  var dayKeyFmt = new Intl.DateTimeFormat('en-CA', { timeZone: TZ, year: 'numeric', month: '2-digit', day: '2-digit' });
  function dayKey(ms) { return dayKeyFmt.format(new Date(ms)); }                 // YYYY-MM-DD in Cairo
  function shiftDay(key, days) {
    var d = new Date(key + 'T12:00:00Z');
    d.setUTCDate(d.getUTCDate() + days);
    return d.toISOString().slice(0, 10);
  }
  function cairoTime(unix) {
    var n = Number(unix);
    return n ? new Intl.DateTimeFormat('en-GB', { timeZone: TZ, hour: '2-digit', minute: '2-digit', hour12: false }).format(new Date(n * 1000)) : '--:--';
  }
  function imageUrl(base, file) {
    var f = file ? String(file).trim() : '';
    return /^[\w.-]+\.(png|jpe?g|webp|gif|svg)$/i.test(f) ? base + encodeURIComponent(f) : '';
  }
  // Arabic-insensitive search: strip diacritics/tatweel, unify alef / ya / ta marbuta.
  function norm(s) {
    return String(s || '').toLowerCase()
      .replace(/[ً-ٰٟـ]/g, '')
      .replace(/[أإآٱ]/g, 'ا').replace(/ى/g, 'ي').replace(/ة/g, 'ه').replace(/ؤ/g, 'و').replace(/ئ/g, 'ي')
      .replace(/\s+/g, ' ').trim();
  }

  async function fetchJson(url, attempts) {
    for (var i = 1; ; i++) {
      var ctrl = new AbortController();
      var timer = setTimeout(function () { ctrl.abort(); }, 9000);
      try {
        var res = await fetch(url, { headers: { Accept: 'application/json' }, signal: ctrl.signal });
        if (!res.ok) throw new Error('HTTP ' + res.status);
        var json = await res.json();
        if (json && json.status === false) throw new Error(json.message || 'API status false');
        return json;
      } catch (err) {
        if (i >= attempts) throw err;
        await wait(1000 * i);
      } finally {
        clearTimeout(timer);
      }
    }
  }
  function matchesUrl(iso) { return WORKER_BASE_URL + '/api/matches/matches_date_get/' + iso + '/' + encodeURI(MATCH_FILTERS) + '/D/60'; }
  function matchInfoUrl(id) { return WORKER_BASE_URL + '/api/matches/match_info/' + encodeURIComponent(id) + '/D/60'; }
  function matchPageUrl(id) { return '/p/match.html?id=' + encodeURIComponent(id); }

  // ------------------------------------------------------------------ parsing (same rules as the home page)
  function statusOf(raw) {
    var s = Number(raw.status);
    if (s === 0) return 'upcoming';
    if (s === 4) return 'finished';
    var kickoff = Number(raw.match_timestamp) * 1000, now = Date.now();
    return kickoff && now >= kickoff - 10 * 60 * 1000 && now <= kickoff + LIVE_WINDOW_MS ? 'live' : 'other';
  }
  // ysscores 'minutes' = match clock in seconds; 2nd half (status 3) already includes 45:00.
  function liveMinute(status, seconds) {
    var secs = Number(seconds);
    if (!(secs > 0)) return '';
    var m = Math.floor(secs / 60) + 1, st = Number(status);
    if (st === 1) return m > 45 ? '45+' + (m - 45) : String(m);
    if (st === 3) { var t = secs >= 2700 ? m : 45 + m; return t > 90 ? '90+' + (t - 90) : String(t); }
    return '';
  }
  function parseMatch(raw) {
    var cc = Array.isArray(raw.channel_commm) && raw.channel_commm.length ? raw.channel_commm[0] : {};
    var champ = raw.championship || {}, home = raw.home_team || {}, away = raw.away_team || {};
    return {
      id: raw.match_id,
      leagueId: String(raw.championship_id != null ? raw.championship_id : ''),
      league: champ.title || 'مباريات',
      leagueLogo: imageUrl(LEAGUE_LOGO_BASE, champ.image),
      round: raw.round || '',
      timestamp: Number(raw.match_timestamp) || 0,
      time: cairoTime(raw.match_timestamp),
      status: statusOf(raw),
      minute: liveMinute(raw.status, raw.minutes),
      home: { name: home.full_title || home.title || '', logo: imageUrl(TEAM_LOGO_BASE, home.image) },
      away: { name: away.full_title || away.title || '', logo: imageUrl(TEAM_LOGO_BASE, away.image) },
      scoreHome: raw.home_scores != null ? raw.home_scores : 0,
      scoreAway: raw.away_scores != null ? raw.away_scores : 0,
      channel: cc.channel_name || '',
      commentator: cc.commentator_name || ''
    };
  }

  // ------------------------------------------------------------------ card templates (home layout)
  var ICON_MIC = '<svg aria-hidden="true" fill="none" stroke="currentColor" stroke-linecap="round" stroke-width="2" viewBox="0 0 24 24"><path d="M12 1a3 3 0 0 0-3 3v8a3 3 0 0 0 6 0V4a3 3 0 0 0-3-3z"/><path d="M19 11a7 7 0 0 1-14 0M12 18v4M8 22h8"/></svg>';
  var ICON_TV = '<svg aria-hidden="true" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" stroke-width="2" viewBox="0 0 24 24"><rect x="2" y="7" width="20" height="14" rx="2"/><path d="m17 2-5 5-5-5"/></svg>';
  function teamHtml(team) {
    return `<div class="team">
        <span class="team__logo"><span class="team__initials">${esc(String(team.name || '').trim().slice(0, 2))}</span>${team.logo ? `<img src="${esc(team.logo)}" alt="${esc(team.name)}" loading="lazy" decoding="async" referrerpolicy="no-referrer" onerror="this.remove()">` : ''}</span>
        <span class="team__name">${esc(team.name)}</span>
      </div>`;
  }
  // Footer chips: known commentator / channel = solid chip; unknown = quiet dashed
  // "يُعلن لاحقًا" chip before kickoff, left out once the match has started.
  function coverageHtml(m) {
    var pre = m.status !== 'live' && m.status !== 'finished';
    function chip(icon, text, pending) {
      return `<span class="match-card__meta${pending ? ' match-card__meta--pending' : ''}">${icon}<span>${esc(text)}</span></span>`;
    }
    var out = '';
    if (m.commentator) out += chip(ICON_MIC, m.commentator); else if (pre) out += chip(ICON_MIC, 'المعلق يُعلن لاحقًا', true);
    if (m.channel) out += chip(ICON_TV, m.channel); else if (pre) out += chip(ICON_TV, 'القناة تُعلن لاحقًا', true);
    return out + '<span class="match-card__more">التفاصيل <span aria-hidden="true">&#8592;</span></span>';
  }
  function badgeHtml(m) {
    if (m.status === 'live') return 'مباشر' + (m.minute ? ` <span dir="ltr">${esc(m.minute)}'</span>` : '');
    return esc(m.status === 'finished' ? 'انتهت' : m.status === 'other' ? 'غير محدد' : 'لم تبدأ');
  }
  function cardHtml(m) {
    var center = m.status === 'live' || m.status === 'finished'
      ? `<span class="match-score"><span>${esc(m.scoreHome)}</span><span class="sep">-</span><span>${esc(m.scoreAway)}</span></span>`
      : `<span class="match-time">${esc(m.time)}</span>`;
    return `<a class="match-card match-card--${m.status === 'other' ? 'upcoming' : m.status}" href="${esc(matchPageUrl(m.id))}">
        <div class="match-card__top"><span class="match-card__league">${esc(m.league)}</span><span class="match-card__round">${esc(m.round)}</span></div>
        <div class="match-card__body">
          ${teamHtml(m.home)}
          <div class="match-center">${center}<span class="badge badge--${m.status === 'live' ? 'live' : m.status === 'finished' ? 'finished' : 'upcoming'}">${badgeHtml(m)}</span></div>
          ${teamHtml(m.away)}
        </div>
        <div class="match-card__bottom">${coverageHtml(m)}</div>
      </a>`;
  }

  // ------------------------------------------------------------------ state
  var today = dayKey(Date.now());
  var hashDate = /date=(\d{4}-\d{2}-\d{2})/.exec(location.hash);
  var state = {
    date: hashDate ? hashDate[1] : today,
    status: 'all', league: 'all', query: '',
    matches: [], loading: true, error: ''
  };
  var cache = {};                                          // date -> { at, matches }
  var liveInfo = {};                                       // match id -> { minute, round, channel, commentator }
  var seq = 0, refreshTimer = null;

  function statusMatches(m, st) {
    if (st === 'all') return true;
    if (st === 'upcoming') return m.status === 'upcoming';
    return m.status === st;
  }
  function textMatches(m) {
    if (!state.query) return true;
    return norm(m.league + ' ' + m.home.name + ' ' + m.away.name).indexOf(state.query) !== -1;
  }
  function leagueRank(id) { var i = PRIORITY.indexOf(id); return i === -1 ? 999 : i; }

  // ------------------------------------------------------------------ rendering
  var EMPTY = {
    all: 'لا توجد مباريات في هذا اليوم.',
    live: 'لا توجد مباريات مباشرة الآن.',
    upcoming: 'لا توجد مباريات لم تبدأ بعد.',
    finished: 'لا توجد مباريات منتهية في هذا اليوم.'
  };
  function renderDays() {
    var offsets = { '-1': shiftDay(today, -1), '0': today, '1': shiftDay(today, 1) };
    Array.prototype.forEach.call(dayBar.querySelectorAll('[data-offset]'), function (b) {
      var on = offsets[b.getAttribute('data-offset')] === state.date;
      b.classList.toggle('is-active', on);
      b.setAttribute('aria-selected', on ? 'true' : 'false');
    });
    var custom = [offsets['-1'], offsets['0'], offsets['1']].indexOf(state.date) === -1;
    var picker = dayBar.querySelector('.mc-picker');
    if (picker) picker.classList.toggle('is-active', custom);
    if (dateInput && dateInput.value !== state.date) dateInput.value = state.date;
    if (dateLabel) {
      try {
        dateLabel.textContent = new Intl.DateTimeFormat('ar-EG', { timeZone: 'UTC', weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' })
          .format(new Date(state.date + 'T12:00:00Z'));
      } catch (e) { dateLabel.textContent = state.date; }
    }
  }
  function renderFilters() {
    // League chips: every league of the day (with counts for the current status + search).
    var leagues = {}, order = [];
    state.matches.forEach(function (m) {
      if (!leagues[m.leagueId]) { leagues[m.leagueId] = { id: m.leagueId, name: m.league, n: 0 }; order.push(leagues[m.leagueId]); }
      if (statusMatches(m, state.status) && textMatches(m)) leagues[m.leagueId].n++;
    });
    if (state.league !== 'all' && !leagues[state.league]) state.league = 'all';
    order.sort(function (a, b) { return leagueRank(a.id) - leagueRank(b.id) || b.n - a.n; });
    var chip = function (id, name, n, on) {
      return `<button type="button" role="tab" class="league-chip${on ? ' is-active' : ''}" aria-selected="${on}" data-league="${esc(id)}"${n === 0 && !on ? ' data-empty' : ''}>${esc(name)}<span class="mc-chip-n">${n}</span></button>`;
    };
    var total = state.matches.filter(function (m) { return statusMatches(m, state.status) && textMatches(m); }).length;
    leagueBar.innerHTML = chip('all', 'كل البطولات', total, state.league === 'all') +
      order.map(function (l) { return chip(l.id, l.name, l.n, state.league === l.id); }).join('');
    leagueBar.hidden = !state.matches.length;

    // Status pills: counts for the current league + search.
    var counts = { all: 0, live: 0, upcoming: 0, finished: 0 };
    state.matches.forEach(function (m) {
      if ((state.league !== 'all' && m.leagueId !== state.league) || !textMatches(m)) return;
      counts.all++;
      if (counts[m.status] != null) counts[m.status]++;
    });
    Array.prototype.forEach.call(statusBar.querySelectorAll('[data-status]'), function (b) {
