    return '<span class="visually-hidden" role="status">جاري تحميل المباريات...</span><div class="mc-sk-group"><span class="sk" style="width:180px;height:18px"></span><div class="match-list">' + card + card + card + card + '</div></div>';
  }
  function renderList() {
    if (state.loading) { listEl.setAttribute('aria-busy', 'true'); listEl.innerHTML = skeleton(); return; }
