      return;
    }
    var list = state.matches.filter(function (m) {
      return statusMatches(m, state.status) && (state.league === 'all' || m.leagueId === state.league) && textMatches(m);
    });
    if (!list.length) {
      var msg = state.query ? 'لا توجد نتائج مطابقة لبحثك.' : EMPTY[state.status];
      listEl.innerHTML = `<div class="match-message mc-empty"><span>${esc(msg)}</span>${state.status !== 'all' || state.query || state.league !== 'all' ? '<button class="px-retry" type="button" data-reset>عرض كل المباريات</button>' : ''}</div>`;
