      if (date === today) matches = await loadLiveInfo(matches);
      if (mySeq !== seq) return;                            // the user picked another day meanwhile
      cache[date] = { at: Date.now(), matches: matches };
      state.matches = matches; state.loading = false; state.error = '';
      renderAll();
    } catch (err) {
      if (mySeq !== seq) return;
      console.warn('[PX League] matches page:', err);
