  var countEl = document.getElementById('pred-count');
  if (!root || !grid || !dayBar || !leagueBar || !authBox || !boardList) return;

  // ------------------------------------------------------------------ helpers
  var ESC = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' };
  function esc(v) { return String(v == null ? '' : v).replace(/[&<>"']/g, function (c) { return ESC[c]; }); }
  function imgUrl(base, value) {
