  function clampGoals(n) { n = Math.round(Number(n)); return isFinite(n) ? Math.max(0, Math.min(MAX_GOALS, n)) : 0; }
  function toHex(bytes) { return Array.prototype.map.call(bytes, function (b) { return ('0' + b.toString(16)).slice(-2); }).join(''); }
  // Score text in RTL order: home goals on the right, like the card (RLM marks fix the bidi order).
