  }

  // ------------------------------------------------------------------ events tab
  var PERIODS = { 1: 'انطلاق المباراة', 2: 'نهاية الشوط الأول', 3: 'بداية الشوط الثاني', 4: 'نهاية المباراة' };
  function minuteText(e) {
    var m = Number(e.time_minute), p = Number(e.time_plus);
    if (!(m >= 0)) return '';
    return m + (p > 0 ? '+' + p : '') + "'";
  }
  function eventHtml(e, homeId, awayId, ev) {
    var type = Number(e.type);
    if (type === 100) {
      var label = PERIODS[e.status];
      if (!label) return '';
      var score = '';
      if (Number(e.status) === 2) score = halfTimeScore(ev);
      if (Number(e.status) === 4) score = (ev.home_scores != null ? ev.home_scores : 0) + ' - ' + (ev.away_scores != null ? ev.away_scores : 0);
      return `<li class="ev ev--period"><span class="ev__period">${esc(label)}${score ? `<b>${esc(score)}</b>` : ''}</span></li>`;
    }
    var side = String(e.team_id) === String(homeId) ? 'home' : String(e.team_id) === String(awayId) ? 'away' : '';
    if (!side) return '';
    var player = nameOf(e.player_name), assist = nameOf(e.assist_player_name);
    var icon = '', title = player, sub = '', cls = '';
    if (type === 1 || type === 4 || type === 5) {
      cls = ' ev--goal'; icon = I.ball;
      sub = type === 4 ? 'هدف عكسي' : type === 5 ? 'ركلة جزاء' : assist ? 'صناعة: ' + assist : 'هدف';
    } else if (type === 2) {
      icon = cardIcon('y'); sub = 'بطاقة صفراء';
    } else if (type === 3) {
      var second = Number(e.status) === 7;
      icon = cardIcon(second ? 'yr' : 'r'); sub = second ? 'إنذار ثانٍ' : 'بطاقة حمراء';
    } else if (type === 8) {
      icon = I.sub;
      title = assist || player;                                // player coming on
      sub = (assist ? 'خروج: ' + player : 'تبديل') + (Number(e.status) === 9 ? ' (إصابة)' : '');
    } else {
      return '';                                               // unverified event code: not shown
    }
    if (!title) return '';
    return `<li class="ev ev--${side}${cls}">
        <div class="ev__body"><span class="ev__icon">${icon}</span><span class="ev__txt"><b>${esc(title)}</b>${sub ? `<small>${esc(sub)}</small>` : ''}</span></div>
        <span class="ev__min" dir="ltr">${esc(minuteText(e))}</span>
      </li>`;
  }
  // Events arrive newest first. When the previous list is an exact tail of the new one (the
  // normal live case: a goal/card was added), only the new <li> items are inserted at the top.
  var lastEvItems = null;
  function sameItems(a, b, offset) {
    for (var i = 0; i < b.length; i++) if (a[i + offset] !== b[i]) return false;
    return true;
  }
  function renderEvents(ev, info) {
    var list = ev && Array.isArray(ev.events) ? ev.events : [];
    var homeId = (info.home_team || {}).row_id, awayId = (info.away_team || {}).row_id;
    var items = list.map(function (e) { return eventHtml(e, homeId, awayId, ev); }).filter(Boolean);
    var el = panels.events;
    if (!items.length) {
      lastEvItems = null;
      setHtml(el, `<div class="match-message"><span>${statusOf(info) === 'upcoming' ? 'لم تبدأ المباراة بعد، ستظهر الأحداث هنا فور انطلاقها.' : 'لا توجد أحداث مسجلة لهذه المباراة.'}</span></div>`);
      return;
    }
    var full = '<ol class="ev-list">' + items.join('') + '</ol>';
    var ol = el.querySelector('.ev-list');
    var added = lastEvItems ? items.length - lastEvItems.length : -1;
    if (ol && added > 0 && sameItems(items, lastEvItems, added)) {
      ol.insertAdjacentHTML('afterbegin', items.slice(0, added).join(''));
      el._pxHtml = full;
    } else {
      setHtml(el, full);                                       // identical -> no-op
    }
    lastEvItems = items;
  }

  // ------------------------------------------------------------------ lineups tab
  var LINE_ORDER = { G: 0, D: 1, M: 2, F: 3 };
  function tagsHtml(p) {
    var t = '';
    var goals = Number(p.goal) || 0;
    for (var i = 0; i < Math.min(goals, 3); i++) t += '<span class="tag-goal">⚽</span>';
    if (Number(p.red)) t += cardIcon('r');
    else if (Number(p.yellow)) t += cardIcon('y');
    if (Number(p.substitute)) t += '<span class="tag-sub" title="تم استبداله">▼</span>';
    return t;
  }
  function playerChip(p, isGk) {
    var pl = p.player || {};
    return `<div class="pl${isGk ? ' pl--gk' : ''}">
        <span class="pl__num">${esc(pl.player_number || '')}${p.rating ? `<span class="pl__rating">${esc(p.rating)}</span>` : ''}${Number(p.captain) ? '<span class="pl__cap">C</span>' : ''}</span>
        <span class="pl__name">${esc(nameOf(pl))}</span>
        <span class="pl__tags">${tagsHtml(p)}</span>
      </div>`;
  }
  // Formation "4-4-1-1" -> rows: [GK], [4], [4], [1], [1]; players ordered G, D, M, F then formation_position
  function pitchHtml(starters, formation) {
    var sorted = starters.slice().sort(function (a, b) {
      var la = LINE_ORDER[a.position] != null ? LINE_ORDER[a.position] : 9, lb = LINE_ORDER[b.position] != null ? LINE_ORDER[b.position] : 9;
      return la - lb || (Number(a.formation_position) || 0) - (Number(b.formation_position) || 0);
    });
    var gk = sorted.filter(function (p) { return p.position === 'G'; });
    var field = sorted.filter(function (p) { return p.position !== 'G'; });
    var lines = String(formation || '').split('-').map(Number).filter(function (n) { return n > 0; });
    var total = lines.reduce(function (a, b) { return a + b; }, 0);
    if (gk.length !== 1 || !lines.length || total !== field.length) return '';   // unknown shape: list only
    var rows = [gk], i = 0;
    lines.forEach(function (n) { rows.push(field.slice(i, i + n)); i += n; });
    return `<div class="pitch">${rows.map(function (r, idx) {
      return `<div class="pitch__line">${r.map(function (p) { return playerChip(p, idx === 0); }).join('')}</div>`;
    }).join('')}</div>`;
  }
  function listHtml(players) {
    return `<ul class="lu-list">${players.map(function (p) {
      var pl = p.player || {};
      return `<li><span class="n">${esc(pl.player_number || '-')}</span><span>${esc(nameOf(pl))}</span>
        <span class="meta">${tagsHtml(p)}${p.rating ? `<span class="r">${esc(p.rating)}</span>` : ''}</span></li>`;
    }).join('')}</ul>`;
  }
  function teamLineupHtml(team, data, side) {
    var tid = String(team.row_id || '');
    var lu = (data.lineup || {})[tid] || {};
    var starters = Array.isArray(lu.lineup) ? lu.lineup : [];
    var subs = Array.isArray(lu.substitutions) ? lu.substitutions : [];
    var injured = ((data.lineup_injureds || {})[tid]) || [];
    var meta = data['0'] || {};
    var formation = meta[side + '_formation'] || '';
    var coach = nameOf(meta[side + '_coach']);
    var logo = imageUrl(TEAM_LOGO_BASE, team.image);
    if (!starters.length) return '';
    var pitch = pitchHtml(starters, formation);
    return `<section class="lu-team">
        <div class="lu-head">${logo ? `<img src="${esc(logo)}" alt="" referrerpolicy="no-referrer" onerror="this.remove()">` : ''}<span>${esc(team.full_title || team.title || '')}</span>${formation ? `<span class="lu-formation">${esc(formation)}</span>` : ''}</div>
        ${pitch || listHtml(starters)}
        ${coach ? `<p class="lu-coach">المدرب: <b>${esc(coach)}</b></p>` : ''}
        ${subs.length ? `<h3 class="lu-sub-title">البدلاء</h3>${listHtml(subs)}` : ''}
        ${injured.length ? `<h3 class="lu-sub-title">الغيابات</h3><ul class="lu-list">${injured.map(function (x) {
          return `<li><span class="n">✚</span><span>${esc(nameOf(x.player))}</span><span class="meta">${esc([x.type_name, x.injury].filter(Boolean).join(' - '))}</span></li>`;
        }).join('')}</ul>` : ''}
      </section>`;
  }
  function renderLineups(data, info) {
    var html = data ? teamLineupHtml(info.home_team || {}, data, 'home') + teamLineupHtml(info.away_team || {}, data, 'away') : '';
    setHtml(panels.lineups, html
      ? `<div class="lu-grid">${html}</div>`
      : '<div class="match-message"><span>لم يتم الإعلان عن التشكيلات بعد.</span></div>');
  }

  // ------------------------------------------------------------------ states
  function loader(el, text) {
    setHtml(el, `<div class="px-loader" role="status"><span class="px-spinner"></span>${text ? `<span>${esc(text)}</span>` : ''}</div>`);
  }
  function message(el, text, retry) {
    if (!setHtml(el, `<div class="match-message"><span>${esc(text)}</span>${retry ? '<button class="px-retry" type="button">إعادة المحاولة</button>' : ''}</div>`)) return;
    var b = el.querySelector('.px-retry');
    if (b) b.addEventListener('click', function () { fetchMatchDetails(false); });
  }

  // ------------------------------------------------------------------ main
  var matchId = new URLSearchParams(location.search).get('id') || '';
  var refreshTimer = null;
  var busy = false;
  var polling = false;        // true while the match is live / not started yet
  var nextDelay = REFRESH_MS; // interval chosen after the last fetch (never the remaining time)
  var lastFetch = 0;
  var failures = 0;           // consecutive failed refreshes -> exponential backoff
  var MAX_TIMER_MS = 6 * 60 * 60 * 1000;
  var MAX_BACKOFF_MS = 5 * 60 * 1000;
  var NO_KICKOFF_MS = 5 * 60 * 1000;                           // upcoming match without a usable timestamp

  // Arm the single timer. Any non-finite or tiny delay is clamped, so a bad value can never
  // turn into setTimeout(fn, NaN/0) and an immediate request loop.
  function arm(ms) {
    clearTimeout(refreshTimer);
    refreshTimer = null;
    if (!polling || document.hidden) return;                  // resumed by visibilitychange/pageshow
    ms = isFinite(ms) ? Math.min(Math.max(ms, 1000), MAX_TIMER_MS) : REFRESH_MS;
    refreshTimer = setTimeout(function () { fetchMatchDetails(true); }, ms);
  }
  function schedule(ms) {                                     // new interval after a fetch
    nextDelay = isFinite(ms) ? Math.min(Math.max(ms, 1000), MAX_TIMER_MS) : REFRESH_MS;
    arm(nextDelay);
  }
  function pause() { clearTimeout(refreshTimer); refreshTimer = null; }
  function resume() {
    if (!polling || document.hidden || busy) return;
    var due = lastFetch + nextDelay - Date.now();
    if (due <= 0) fetchMatchDetails(true); else arm(due);     // nextDelay stays the full interval
  }
  function kickoffMs(d) {                                     // 0 when missing / not a positive number
    var t = Number(d && d.match_timestamp);
    return isFinite(t) && t > 0 ? t * 1000 : 0;
  }
  // Decide the next refresh from the verified states only (0 = upcoming, 4 = finished, other
  // codes = live near kick-off, see statusOf). No undocumented status code is interpreted.
  function planNext(st, info) {
    if (st === 'live') { polling = true; schedule(REFRESH_MS); return; }
    if (st === 'upcoming') {
      var kick = kickoffMs(info), now = Date.now();
      if (!kick) { polling = true; schedule(NO_KICKOFF_MS); return; }   // slow, bounded
      if (now > kick + LIVE_WINDOW_MS) { polling = false; pause(); return; }   // still "not started" 3.5 h after kick-off: postponed / stale, stop
      var untilWindow = kick - 30 * 60 * 1000 - now;
      polling = true;
      schedule(untilWindow > REFRESH_MS ? untilWindow : REFRESH_MS);  // wake 30 min before kick-off
      return;
    }
    polling = false;                                         // finished / other: no more polling
    pause();
  }
  function heroShown() { return !!(heroParts && hero.contains(heroParts.center)); }
  // match_info must be an object with both teams; anything else (null body, wrapper without
  // data, array, error page parsed as JSON) is treated as a failed refresh.
  function isMatchInfo(d) {
    return !!d && typeof d === 'object' && !Array.isArray(d) &&
      !!d.home_team && typeof d.home_team === 'object' && !!d.away_team && typeof d.away_team === 'object';
  }
  document.addEventListener('visibilitychange', function () { if (document.hidden) pause(); else resume(); });
  window.addEventListener('pagehide', pause);                 // leaving / entering the back-forward cache
  window.addEventListener('pageshow', function (e) { if (e.persisted) resume(); });

  async function fetchMatchDetails(silent) {
    if (busy) return;
    pause();
    if (!/^\d{1,12}$/.test(matchId)) {
      message(hero, 'لم يتم تحديد المباراة. اختر مباراة من الصفحة الرئيسية.', false);
      setHtml(panels.events, ''); setHtml(panels.lineups, '');
      return;
    }
    // A retry while a score is on screen keeps the hero (last valid score) and reloads the panels only
    if (!silent) { if (!heroShown()) loader(hero, 'جاري تحميل المباراة...'); loader(panels.events); loader(panels.lineups); }
    if (!WORKER_BASE_URL || WORKER_BASE_URL.indexOf('<MY_WORKER_URL>') !== -1) {
      console.error('[PX League] Set PXL_WORKER_BASE_URL (top of the theme) to load match details.');
      return;                                                  // keep the spinners
    }
    busy = true;
    var ok = false, st = '', info = null;
    try {
      info = await fetchJson(api('match_info', matchId), silent ? 1 : 3);
      if (!isMatchInfo(info)) throw new Error('malformed match_info');
      applyStream(info.stream);                                // stream merged in by the Worker
      var results = await Promise.allSettled([
        Number(info.events) ? fetchJson(api('matches_event', matchId), silent ? 1 : 2).then(function (d) {
          if (!d || typeof d !== 'object' || !Array.isArray(d.events)) throw new Error('malformed matches_event');
          return d;
        }) : Promise.resolve(null),
        Number(info.lineup) ? fetchJson(api('matches_lineup', matchId), silent ? 1 : 2).then(function (d) {
          if (!d || typeof d !== 'object' || !d.lineup || typeof d.lineup !== 'object') throw new Error('malformed matches_lineup');
          return d;
        }) : Promise.resolve(null)
      ]);
      var ev = results[0].status === 'fulfilled' ? results[0].value : null;
      var lu = results[1].status === 'fulfilled' ? results[1].value : null;

      st = renderHero(info, ev);                               // a throw here counts as a failed refresh
      // Panels: a failed or malformed response keeps what is on screen (silent) or offers a retry
      try {
        if (results[0].status === 'rejected') { if (!silent) message(panels.events, 'تعذّر تحميل الأحداث.', true); }
        else renderEvents(ev || {}, info);
      } catch (e) { console.warn('[PX League] render events:', e); }
      try {
        if (results[1].status === 'rejected') { if (!silent) message(panels.lineups, 'تعذّر تحميل التشكيلات.', true); }
        else renderLineups(lu, info);
      } catch (e) { console.warn('[PX League] render lineups:', e); }
      ok = true;
    } catch (err) {
      console.warn('[PX League] match details:', err);
      if (!silent) {
        if (!heroShown()) {
          message(hero, String(err && err.message).indexOf('404') !== -1 ? 'المباراة غير موجودة.' : 'تعذّر تحميل بيانات المباراة.', true);
          setHtml(panels.events, ''); setHtml(panels.lineups, '');
        } else {                                               // keep the score, offer a retry in the panels
          message(panels.events, 'تعذّر تحميل الأحداث.', true);
          message(panels.lineups, 'تعذّر تحميل التشكيلات.', true);
        }
      }
    } finally {
      busy = false;
      lastFetch = Date.now();
      // Every outcome ends here, so neither a failed request, a malformed body, a render
      // exception nor a failed manual retry can leave a polling match without a timer.
      if (ok) {
        failures = 0;
        planNext(st, info);
      } else if (polling) {
        failures++;                                            // 60 s, 120 s, 240 s, then 5 min
        schedule(Math.min(REFRESH_MS * Math.pow(2, failures), MAX_BACKOFF_MS));
      }
    }
  }

  // ------------------------------------------------------------------ tabs
  function selectTab(btn, focus) {
    tabs.forEach(function (t) {
      var on = t === btn;
      t.classList.toggle('is-active', on);
      t.setAttribute('aria-selected', on ? 'true' : 'false');
      t.tabIndex = on ? 0 : -1;
      panels[t.getAttribute('data-tab')].hidden = !on;
    });
    if (focus) btn.focus();
    try { history.replaceState(null, '', location.pathname + location.search + '#' + btn.getAttribute('data-tab')); } catch (e) {}
  }
  page.querySelector('.match-tabs').addEventListener('click', function (e) {
    var b = e.target.closest('.match-tab');
    if (b) selectTab(b, false);
  });
  page.querySelector('.match-tabs').addEventListener('keydown', function (e) {
    if (e.key !== 'ArrowLeft' && e.key !== 'ArrowRight') return;
    var i = tabs.indexOf(document.activeElement);
    if (i === -1) return;
    e.preventDefault();
    selectTab(tabs[(i + (e.key === 'ArrowLeft' ? 1 : -1) + tabs.length) % tabs.length], true);   // RTL
  });
  var initialTab = tabs.filter(function (t) { return '#' + t.getAttribute('data-tab') === location.hash; })[0];
  if (initialTab) selectTab(initialTab, false);

  // ------------------------------------------------------------------ live stream (Match Controller)
  // The Worker merges the dashboard's match_settings into match_info:
  //   data.stream = { channel, r2_slug }   (absent = no stream)
  // match_info is refreshed every 30 s from 30 min before kick-off and while live, so a
  // stream attached or removed in the dashboard follows on the next refresh. No extra request.
  var STREAM_PLAYER_BASE = window.PXL_STREAM_PLAYER_BASE || 'https://live.smarterwho.site/player/';
  var STREAM_KEY_RE = /^[A-Za-z0-9_-]{1,64}$/;
  var streamBox = document.getElementById('match-stream');
  var streamSlot = document.getElementById('px-player-slot');
  var streamSrc = null;
  function streamUrl(s) {
    var channel = String(s.channel || ''), slug = String(s.r2_slug || '');
    var okChannel = STREAM_KEY_RE.test(channel), okSlug = STREAM_KEY_RE.test(slug);
    if (!okChannel && !okSlug) return '';
    var u = new URL(STREAM_PLAYER_BASE);
    if (okChannel) u.searchParams.set('channel', channel);
    if (okSlug) u.searchParams.set('r2', slug);
    return u.toString();
  }
  function showStream(src) {
    if (!streamBox || !streamSlot || src === streamSrc) return;   // same stream: never reload the player
    streamSrc = src;
    streamSlot.textContent = '';
    if (!src) { streamBox.hidden = true; return; }
    var f = document.createElement('iframe');
    f.src = src;
    f.title = 'البث المباشر';
    f.setAttribute('allow', 'autoplay; fullscreen; encrypted-media; picture-in-picture');
    f.setAttribute('allowfullscreen', 'true');
    streamSlot.appendChild(f);
    streamBox.hidden = false;
  }
  function applyStream(s) { showStream(s && typeof s === 'object' ? streamUrl(s) : ''); }

  window.fetchMatchDetails = fetchMatchDetails;
  fetchMatchDetails(false);
})();
//

