(function () {
  var slot = document.getElementById('px-player-slot');
  var body = document.getElementById('px-post-body');
  if (!slot || !body) return;

  var frame = null;
  var marker = body.querySelector('[data-stream-src]');
  if (marker) {
    var src = marker.getAttribute('data-stream-src') || '';
    if (/^https:\/\//i.test(src)) {
      frame = document.createElement('iframe');
      frame.src = src;
    }
    marker.remove();
  } else {
    frame = body.querySelector('iframe');
  }
  if (!frame) return;   // regular article: the arena stays hidden, the post shows normally

  frame.setAttribute('allow', 'autoplay; fullscreen; encrypted-media; picture-in-picture');
  frame.setAttribute('allowfullscreen', 'true');
  frame.setAttribute('title', document.title);
  frame.removeAttribute('width');
  frame.removeAttribute('height');
  frame.removeAttribute('style');
  slot.textContent = '';
  slot.appendChild(frame);

  // Stream found: show the arena (its title replaces the article title)
  var arena = document.getElementById('px-arena');
  var postTitle = document.getElementById('px-post-title');
  if (arena) arena.hidden = false;
  if (postTitle) postTitle.hidden = true;
  if (!arena) return;

  // Ads: only slots with real ad code, and only after the player iframe has loaded
  // (never beside an empty player or a loading placeholder). adsbygoogle is pushed
  // here, once the slot is visible: a push into a hidden slot fails for good
  // ("availableWidth=0"), which is why the widgets must not push themselves.
  var slots = arena.querySelectorAll('.ad-slot');
  for (var i = 0; i < slots.length; i++) {
    if (slots[i].querySelector('ins.adsbygoogle, iframe, img')) slots[i].classList.add('is-filled');
  }
  var shown = false;
  function showAds() {
    if (shown) return;
    shown = true;
    arena.classList.add('is-ready');
    var ins = arena.querySelectorAll('.ad-slot.is-filled ins.adsbygoogle:not([data-adsbygoogle-status])');
    for (var j = 0; j < ins.length; j++) {
      try { (window.adsbygoogle = window.adsbygoogle || []).push({}); } catch (e) {}
    }
  }
  frame.addEventListener('load', showAds, { once: true });
})();
//

