(function () {
  'use strict';

  // ------------------------------------------------------------------ configuration
  var WORKER_BASE_URL = window.PXL_WORKER_BASE_URL || '';    // set once at the top of the file (SETTINGS)
  var MATCH_FILTERS = '[]/[]/["8634"]';
  var TEAM_LOGO_BASE = 'https://imgs.ysscores.com/teams/128/';
  var LEAGUE_LOGO_BASE = 'https://imgs.ysscores.com/championship/64/';
  var MAX_ATTEMPTS = 3;                                       // tries before an error is shown
  var REFRESH_LIVE_MS = 30 * 1000;                            // silent refresh while a match is live
  var REFRESH_IDLE_MS = 2 * 60 * 1000;                        // ... and when nothing is live (battery)
  var LIVE_WINDOW_MS = 3.5 * 60 * 60 * 1000;

  var container = document.getElementById('matches-api-container');
  if (!container) return;

  // ------------------------------------------------------------------ helpers
  var ESC = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' };
  function esc(v) { return String(v == null ? '' : v).replace(/[&<>"']/g, function (c) { return ESC[c]; }); }
  function wait(ms) { return new Promise(function (r) { setTimeout(r, ms); }); }

  function cairoDate(d) {                                     // YYYY-MM-DD in Africa/Cairo
    var p = new Intl.DateTimeFormat('en-CA', { timeZone: 'Africa/Cairo' }).formatToParts(d);
    var get = function (t) { return p.find(function (x) { return x.type === t; }).value; };
    return get('year') + '-' + get('month') + '-' + get('day');
  }
  function cairoTime(unixSeconds) {                           // HH:MM in Africa/Cairo
    var n = Number(unixSeconds);
    if (!n) return '--:--';
    return new Intl.DateTimeFormat('en-GB', { timeZone: 'Africa/Cairo', hour: '2-digit', minute: '2-digit', hour12: false }).format(new Date(n * 1000));
  }
  function imageUrl(base, file) {                             // only plain file names like "4151761254960.png"
    var f = file ? String(file).trim() : '';
    return /^[\w.-]+\.(png|jpe?g|webp|gif|svg)$/i.test(f) ? base + encodeURIComponent(f) : '';
  }

  var dateEl = document.getElementById('fixtures-date');
  try {
    dateEl.textContent = new Intl.DateTimeFormat('ar-EG', { timeZone: 'Africa/Cairo', weekday: 'long', day: 'numeric', month: 'long' }).format(new Date());
  } catch (e) { /* old browser: no date label */ }

  async function fetchJson(url, attempts) {
    for (var i = 1; ; i++) {
      var ctrl = new AbortController();
      var timer = setTimeout(function () { ctrl.abort(); }, 9000);
      try {
        var res = await fetch(url, { headers: { Accept: 'application/json' }, cache: 'no-store', signal: ctrl.signal });
        if (!res.ok) throw new Error('HTTP ' + res.status);
        var json = await res.json();
        if (json && json.status === false) throw new Error(json.message || 'API status false');
        return json;
      } catch (err) {
        if (i >= attempts) throw err;
        await wait(1000 * i);                                 // 1 s, 2 s between attempts
      } finally {
        clearTimeout(timer);
      }
    }
  }

  function matchesUrl(isoDate) {
    return WORKER_BASE_URL + '/api/matches/matches_date_get/' + isoDate + '/' + encodeURI(MATCH_FILTERS) + '/D/60';
  }
  function matchPageUrl(id) {                                 // dedicated match details page
    return '/p/match.html?id=' + encodeURIComponent(id);
  }
  function matchInfoUrl(id) {
    return WORKER_BASE_URL + '/api/matches/match_info/' + encodeURIComponent(id) + '/D/60';
  }

  // ------------------------------------------------------------------ parsing
  function statusOf(raw) {
    var s = Number(raw.status);
    if (s === 0) return 'upcoming';
    if (s === 4) return 'finished';
    var kickoff = Number(raw.match_timestamp) * 1000;
    var now = Date.now();
    return kickoff && now >= kickoff - 10 * 60 * 1000 && now <= kickoff + LIVE_WINDOW_MS ? 'live' : 'other';
  }

  // ysscores 'minutes' (match_info) = the MATCH CLOCK in seconds, verified live 2026-11-17:
  // status 1 = 1st half, counted from kick-off; status 3 = 2nd half and the value already
  // includes the first 45:00 (46:10 into the 2nd half -> 5467 s). Adding another 45 produced
  // "90+45". A 2nd-half value below 45:00 is treated as time since the restart.
  // Any other live code (half-time, extra time...) gets no minute rather than a wrong one.
  function liveMinute(status, seconds) {
    var secs = Number(seconds);
    if (!(secs > 0)) return '';
    var m = Math.floor(secs / 60) + 1;
    var st = Number(status);
    if (st === 1) return m > 45 ? '45+' + (m - 45) : String(m);
    if (st === 3) { var t = secs >= 2700 ? m : 45 + m; return t > 90 ? '90+' + (t - 90) : String(t); }
    return '';
  }

  // Status badge HTML. Live: "مباشر" + ONLY the minute (never the status code), with the
  // minute isolated as LTR so "61'" / "45+2'" render correctly inside the RTL page.
  function liveBadgeHtml(m) {
    if (m.status === 'live') {
      return 'مباشر' + (m.minute ? ` <span dir="ltr">${esc(m.minute)}'</span>` : '');
    }
    return esc(m.status === 'finished' ? 'انتهت' : m.status === 'other' ? 'غير محدد' : 'لم تبدأ');
  }

  function parseMatch(raw) {
    var cc = Array.isArray(raw.channel_commm) && raw.channel_commm.length ? raw.channel_commm[0] : {};
    var champ = raw.championship || {};
    var home = raw.home_team || {};
    var away = raw.away_team || {};
    return {
      id: raw.match_id,
      leagueId: String(raw.championship_id != null ? raw.championship_id : ''),
      league: champ.title || 'مباريات',
      leagueLogo: imageUrl(LEAGUE_LOGO_BASE, champ.image),
      round: raw.round || '',
      timestamp: Number(raw.match_timestamp) || 0,
      time: cairoTime(raw.match_timestamp),
      status: statusOf(raw),
      minute: liveMinute(raw.status, raw.minutes),
      home: { name: home.full_title || home.title || '', logo: imageUrl(TEAM_LOGO_BASE, home.image) },
      away: { name: away.full_title || away.title || '', logo: imageUrl(TEAM_LOGO_BASE, away.image) },
      scoreHome: raw.home_scores != null ? raw.home_scores : 0,
      scoreAway: raw.away_scores != null ? raw.away_scores : 0,
      channel: cc.channel_name || '',
      commentator: cc.commentator_name || ''
    };
  }

  // ------------------------------------------------------------------ priority sort
  // Popular leagues (championship_id). IDs below are the ones this theme already uses on the
  // standings page. Add the UEFA Champions League id here once you have it from the API.
  var VIP_LEAGUE_IDS = ['937599', '938652', '20580897'];   // Premier League, La Liga, CAF Champions League
  var VIP = {};
  VIP_LEAGUE_IDS.forEach(function (id) { VIP[String(id)] = true; });

  // 1) live matches first, 2) VIP leagues, 3) everything else; inside each tier by kick-off time.
  // Matches without a kick-off time go last in their tier; the id keeps the order stable.
  function tierOf(m) { return m.status === 'live' ? 0 : VIP[m.leagueId] ? 1 : 2; }
  function sortMatches(list) {
    return list.slice().sort(function (a, b) {
      var ta = a.timestamp || Number.MAX_SAFE_INTEGER, tb = b.timestamp || Number.MAX_SAFE_INTEGER;
      return tierOf(a) - tierOf(b) || ta - tb || String(a.id).localeCompare(String(b.id));
    });
  }

  // ------------------------------------------------------------------ templates (current layout)
  var ICON_MIC = '<svg aria-hidden="true" fill="none" stroke="currentColor" stroke-linecap="round" stroke-width="2" viewBox="0 0 24 24"><path d="M12 1a3 3 0 0 0-3 3v8a3 3 0 0 0 6 0V4a3 3 0 0 0-3-3z"/><path d="M19 11a7 7 0 0 1-14 0M12 18v4M8 22h8"/></svg>';
  var ICON_TV = '<svg aria-hidden="true" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" stroke-width="2" viewBox="0 0 24 24"><rect x="2" y="7" width="20" height="14" rx="2"/><path d="m17 2-5 5-5-5"/></svg>';

  function teamHtml(team) {
    var initials = esc(String(team.name || '').trim().slice(0, 2));
    return `
      <div class="team">
        <span class="team__logo">
          <span class="team__initials">${initials}</span>
          ${team.logo ? `<img src="${esc(team.logo)}" alt="${esc(team.name)}" loading="lazy" decoding="async" referrerpolicy="no-referrer" onerror="this.remove()">` : ''}
        </span>
        <span class="team__name">${esc(team.name)}</span>
      </div>`;
  }

  // A card is split into regions so a refresh can patch only the parts whose markup changed.
  // Team blocks (logos) are never re-rendered once a card exists.
  function cardClass(m) { return 'match-card match-card--' + (m.status === 'other' ? 'upcoming' : m.status); }
  function cardTopHtml(m) {
    return `<span class="match-card__league">${esc(m.league)}</span><span class="match-card__round">${esc(m.round)}</span>`;
  }
  function cardCenterHtml(m) {
    var center = m.status === 'live' || m.status === 'finished'
      ? `<span class="match-score"><span>${esc(m.scoreHome)}</span><span class="sep">-</span><span>${esc(m.scoreAway)}</span></span>`
      : `<span class="match-time">${esc(m.time)}</span>`;
    return `${center}<span class="badge badge--${m.status === 'live' ? 'live' : m.status === 'finished' ? 'finished' : 'upcoming'}">${liveBadgeHtml(m)}</span>`;
  }
  // Footer chips: known commentator / channel = solid chip; unknown = quiet dashed
  // "يُعلن لاحقًا" chip before kickoff, left out once the match has started.
  function cardBottomHtml(m) {
    var pre = m.status !== 'live' && m.status !== 'finished';
    function chip(icon, text, pending) {
      return `<span class="match-card__meta${pending ? ' match-card__meta--pending' : ''}">${icon}<span>${esc(text)}</span></span>`;
    }
    var out = '';
    if (m.commentator) out += chip(ICON_MIC, m.commentator); else if (pre) out += chip(ICON_MIC, 'المعلق يُعلن لاحقًا', true);
    if (m.channel) out += chip(ICON_TV, m.channel); else if (pre) out += chip(ICON_TV, 'القناة تُعلن لاحقًا', true);
    return out + '<span class="match-card__more">التفاصيل <span aria-hidden="true">&#8592;</span></span>';
  }
  function cardParts(m) {
    return { cls: cardClass(m), top: cardTopHtml(m), center: cardCenterHtml(m), bottom: cardBottomHtml(m) };
  }

  function cardHtml(m, entering) {
    var p = cardParts(m);
    cardState[m.id] = p;                                      // what is on screen, for later diffs
    return `
      <a class="${p.cls}${entering ? ' match-card--enter' : ''}" data-mid="${esc(m.id)}" href="${esc(matchPageUrl(m.id))}">
        <div class="match-card__top">${p.top}</div>
        <div class="match-card__body">
          ${teamHtml(m.home)}
          <div class="match-center">${p.center}</div>
          ${teamHtml(m.away)}
        </div>
        <div class="match-card__bottom">${p.bottom}</div>
      </a>`;
  }

  // ------------------------------------------------------------------ states
  function showLoading() {
    layoutKey = '';
    visibleCount = PAGE_SIZE;                                 // a full reload starts with 4 again
    container.setAttribute('aria-busy', 'true');
    container.innerHTML = '<div class="px-loader" role="status"><span class="px-spinner"></span><span>جاري تحميل المباريات...</span></div>';
  }
  function showMessage(text, withRetry) {
    layoutKey = '';
    container.setAttribute('aria-busy', 'false');
    container.innerHTML = `<div class="match-message"><span>${esc(text)}</span>${withRetry ? '<button class="px-retry" type="button">إعادة المحاولة</button>' : ''}</div>`;
    var btn = container.querySelector('.px-retry');
    if (btn) btn.addEventListener('click', function () { loadMatches(false); });
  }
  // Rendering strategy (one flat, priority-sorted list; only the first visibleCount are in the DOM)
  //  - Same visible matches in the same order as on screen (the normal 30 s refresh):
  //    patch in place. Only regions whose markup changed are written, e.g. one score + minute.
  //  - Visible order changed (a match went live and moved up, a match was added/removed):
  //    re-render the visible cards, keeping how many the viewer has opened with "عرض المزيد".
  //  - "عرض المزيد" appends the next batch; existing cards are not touched.
  var PAGE_SIZE = 4;                                          // cards shown on first load
  var LOAD_MORE_STEP = 8;                                     // cards added per "عرض المزيد" click
  var visibleCount = PAGE_SIZE;
  var sortedMatches = [];                                     // full sorted list of the last refresh
  var cardState = {};                                         // match id -> parts currently on screen
  var layoutKey = '';                                         // visible match ids as rendered
  var listEl = null, moreWrap = null, moreBtn = null;

  function keyOf(list) {
    return list.map(function (m) { return m.id; }).join(',');
  }
  // List + button skeleton. Rebuilt only after a loader/message replaced the container.
  function ensureShell() {
    if (listEl && container.contains(listEl)) return;
    container.innerHTML = '<div class="match-list"></div>' +
      '<div class="load-more-wrap" hidden><button class="load-more" type="button">' +
      '<span>عرض المزيد</span><span class="load-more__count"></span></button></div>';
    listEl = container.querySelector('.match-list');
    moreWrap = container.querySelector('.load-more-wrap');
    moreBtn = moreWrap.querySelector('.load-more');
    moreBtn.addEventListener('click', loadMore);
    layoutKey = '';
  }
  function updateMoreButton() {
    var remaining = sortedMatches.length - visibleCount;
    moreWrap.hidden = remaining <= 0;
    if (remaining > 0) moreBtn.querySelector('.load-more__count').textContent = '(' + remaining + ')';
  }
  function loadMore() {
    var start = listEl.children.length;
    var next = sortedMatches.slice(start, start + LOAD_MORE_STEP);
    if (!next.length) { updateMoreButton(); return; }
    listEl.insertAdjacentHTML('beforeend', next.map(function (m) { return cardHtml(m, true); }).join(''));
    visibleCount = start + next.length;
    layoutKey = keyOf(sortedMatches.slice(0, visibleCount));
    updateMoreButton();
    // Keyboard / screen-reader users continue at the first new card; when the button disappears
    // focus would otherwise fall back to <body>.
    var first = listEl.children[start];
    if (first && document.activeElement === moreBtn) first.focus({ preventScroll: true });
  }
  function patchCard(el, m) {
    var prev = cardState[m.id], next = cardParts(m);
    if (!prev) return false;
    if (prev.cls !== next.cls) el.className = next.cls;
    if (prev.top !== next.top) el.querySelector('.match-card__top').innerHTML = next.top;
    if (prev.center !== next.center) el.querySelector('.match-center').innerHTML = next.center;
    if (prev.bottom !== next.bottom) el.querySelector('.match-card__bottom').innerHTML = next.bottom;
    cardState[m.id] = next;
    return true;
  }
  function patch(list) {
    var els = listEl.children;
    if (els.length !== list.length) return false;
    for (var i = 0; i < list.length; i++) {
      if (els[i].getAttribute('data-mid') !== String(list[i].id) || !patchCard(els[i], list[i])) return false;
    }
    return true;
  }
  function render(matches) {
    sortedMatches = sortMatches(matches);
    if (!sortedMatches.length) { layoutKey = ''; showMessage(endedCount ? 'انتهت جميع مباريات اليوم.' : 'لا توجد مباريات اليوم.', false); return; }
    ensureShell();
    container.setAttribute('aria-busy', 'false');
    var visible = sortedMatches.slice(0, visibleCount);
    var key = keyOf(visible);
    if (!(key === layoutKey && patch(visible))) {
      cardState = {};
      listEl.innerHTML = visible.map(function (m) { return cardHtml(m, false); }).join('');
      layoutKey = key;
    }
    updateMoreButton();
  }

  // ------------------------------------------------------------------ live matches: minute + channel
  var liveInfo = {};                                          // match_id -> { minute, round, channel, commentator }

  function withLiveInfo(m) {
    var info = liveInfo[m.id];
    if (!info) return m;
    if (info.minute) m.minute = info.minute;
    if (info.round && !m.round) m.round = info.round;
    if (info.channel && !m.channel) m.channel = info.channel;
    if (info.commentator && !m.commentator) m.commentator = info.commentator;
    return m;
  }

  async function loadLiveInfo(matches) {
    var live = matches.filter(function (m) { return m.status === 'live'; }).slice(0, 12);
    await Promise.all(live.map(async function (m) {
      try {
        var json = await fetchJson(matchInfoUrl(m.id), 1);
        var d = (json && json.data) || {};
        var cc = Array.isArray(d.channel_commm) && d.channel_commm.length ? d.channel_commm[0] : {};
        liveInfo[m.id] = {
          minute: liveMinute(d.status, d.minutes),
          round: d.round || '',
          channel: cc.channel_name || '',
          commentator: cc.commentator_name || ''
        };
      } catch (e) { /* card stays without minute */ }
    }));
    return matches.map(withLiveInfo);
  }

  // ------------------------------------------------------------------ load
  var hasData = false;
  var loading = false;
  var endedCount = 0;          // finished matches hidden from today's list
  var anyLive = false;
  var lastLoad = 0;
  var refreshTimer = null;

  // One setTimeout chain instead of setInterval: nothing runs while the tab is hidden or the
  // page sits in the back-forward cache, and the next tick waits for the previous request.
  function refreshDelay() { return anyLive ? REFRESH_LIVE_MS : REFRESH_IDLE_MS; }
  function schedule() {
    clearTimeout(refreshTimer);
    refreshTimer = null;
    if (!hasData || document.hidden) return;
    var due = Math.max(0, lastLoad + refreshDelay() - Date.now());
    refreshTimer = setTimeout(function () { loadMatches(true); }, due);
  }
  function pause() { clearTimeout(refreshTimer); refreshTimer = null; }
  document.addEventListener('visibilitychange', function () { if (document.hidden) pause(); else schedule(); });
  window.addEventListener('pagehide', pause);
  window.addEventListener('pageshow', function (e) { if (e.persisted) schedule(); });

  async function loadMatches(silent) {
    if (loading) return;
    loading = true;
    pause();
    if (!silent || !hasData) showLoading();
    try {
      if (!WORKER_BASE_URL || WORKER_BASE_URL.indexOf('<MY_WORKER_URL>') !== -1) {
        // Not configured yet: keep the spinner, tell the site owner in the console
        console.error('[PX League] Set PXL_WORKER_BASE_URL (top of the theme) to your Cloudflare Worker URL.');
        return;
      }
      // Background refreshes make ONE attempt: the next tick is the retry. Three attempts per
      // tick tripled Worker requests from every open tab during an outage.
      var json = await fetchJson(matchesUrl(cairoDate(new Date())), silent && hasData ? 1 : MAX_ATTEMPTS);
      // A 200 without a data array (error page, wrapper without data) must not replace the
      // cards with "no matches today": treat it as a failed refresh and keep the last good data.
      if (!json || !Array.isArray(json.data)) throw new Error('malformed matches_date_get');
      // Finished matches (status 4, "انتهت") are not shown; a match that ends while the page is
      // open disappears at the next refresh.
      var parsed = json.data.map(parseMatch);
      var matches = parsed.filter(function (m) { return m.status !== 'finished'; });
      endedCount = parsed.length - matches.length;
      matches = await loadLiveInfo(matches);                  // live minute + channel before showing
      render(matches);
      anyLive = matches.some(function (m) { return m.status === 'live'; });
      hasData = true;
    } catch (err) {
      console.warn('[PX League] matches:', err);
      if (!hasData) showMessage('تعذّر تحميل المباريات حاليًا.', true);   // keep last good data on refresh errors
    } finally {
      lastLoad = Date.now();
      loading = false;
      schedule();
    }
  }

  loadMatches(false);
})();
//
